'Cr_Guide_How' => 'Cara mendaftarkannya',
'Cr_Guide_How_It_Works' => 'Cara kerjanya',
'Cr_Guide_Meaning' => 'Arti',
'Cr_Guide_T_Statuses' => 'Status',
'Cr_Guide_Statuses_Note' => 'Status hanya bergerak maju, sehingga pembaruan yang terlambat tidak pernah menarik paket kembali ke status sebelumnya. Paket yang sudah terkirim tetap dapat dilaporkan sebagai dalam proses retur atau diretur.',
'Cr_Guide_S_booked' => 'Kurir sudah menerima pesanan; belum ada yang menjemputnya. Pemesanan hanya dapat dibatalkan pada tahap ini.',
'Cr_Guide_S_picked_up' => 'Kurir telah menjemput paket.',
'Cr_Guide_S_in_transit' => 'Berpindah antar-hub, di bea cukai, atau ditahan.',
'Cr_Guide_S_out_for_delivery' => 'Dibawa kurir pengantar hari ini.',
'Cr_Guide_S_failed_attempt' => 'Penerima tidak di tempat, menolak, atau alamat salah. Kurir akan mencoba lagi atau mengembalikannya.',
'Cr_Guide_S_delivered' => 'Diserahkan kepada pelanggan. Jumlah COD menjadi berstatus ditagih oleh kurir.',
'Cr_Guide_S_returning' => 'Sedang dalam perjalanan kembali kepada Anda.',
'Cr_Guide_S_returned' => 'Sudah kembali kepada Anda: menunggu di Retur untuk ditinjau, atau dikembalikan ke stok secara otomatis.',
'Cr_Guide_S_cancelled' => 'Pemesanan dibatalkan.',
'Cr_Guide_T_Booking' => 'Memesan pengiriman',
'Cr_Guide_B_Booking' => 'Kirim ke kurir mengisi formulir dari penjualan: penerima, alamat, jumlah yang masih terutang sebagai COD, dan berat produk. Kurir yang memiliki daftar kota sendiri menampilkan pemilih, dan pilihan Anda diingat untuk kota tersebut. Agregator, DHL, FedEx, UPS, dan Lalamove menyediakan Bandingkan tarif: pilih harga dan Pesan akan membelinya. Beberapa penjualan dapat dipesan sekaligus dari daftar penjualan.',
'Cr_Guide_T_Cod' => 'Bayar di tempat',
'Cr_Guide_B_Cod' => 'Paket COD berpindah dari Belum ditagih ke Ditagih oleh kurir (saat diantar) lalu ke Dicairkan ke Anda. Kurir yang melaporkan pencairan memindahkan langkah terakhir sendiri; untuk yang lain gunakan Perbarui COD. Jika akun dipilih di Pengaturan Kurir, pencairan dicatat sebagai pembayaran pada penjualan. Biaya kurir dapat disimpan sebagai beban setelah paket selesai.',
'Cr_Guide_T_Returns' => 'Paket yang diretur',
'Cr_Guide_B_Returns' => 'Secara default, paket yang diretur menunggu di Pengiriman Kurir pada Retur untuk ditinjau. Kembalikan ke stok membuat retur penjualan untuk seluruh pesanan dan mengembalikan item ke stok; Abaikan tidak mengembalikan apa pun, untuk paket yang rusak atau hilang. Sebagai gantinya, Pengaturan Kurir dapat mengembalikan ke stok secara otomatis.',
'Cr_Guide_T_Customers' => 'Pesan pelanggan dan halaman pelacakan',
'Cr_Guide_B_Customers' => 'Notifikasi pelanggan di Pengaturan Kurir mengirim SMS, email, atau WhatsApp pada status yang Anda centang, masing-masing sekali per paket, dengan teks Anda sendiri. Halaman pelacakan di toko daring Anda memungkinkan pelanggan memantau paket dengan nomor resi, atau dengan nomor pesanan dan telepon. Pelanggan yang sering meretur paket mendapat lencana risiko retur saat Anda memesan pengiriman.',
'Cr_Guide_T_Labels' => 'Label',
'Cr_Guide_B_Labels' => 'Cetak label memberikan label milik kurir jika kurir menerbitkannya (PDF, tautan, atau gambar), jika tidak maka label Stocky dengan barcode resi dan jumlah yang harus ditagih. Izinkan pop-up untuk situs ini agar dapat mencetak. DHL, FedEx, dan UPS hanya memberikan labelnya sekali, saat pemesanan, dan Stocky menyimpannya untuk dicetak ulang.',
'Cr_Guide_T_Faq' => 'Pemecahan masalah',
'Cr_Guide_Q_Test' => 'Uji koneksi gagal',
'Cr_Guide_A_Test' => 'Kunci mode uji digunakan dengan Mode uji dan kunci live dengan Live; keduanya berbeda. Buka Log kurir dan baca jawaban kurir untuk mengetahui alasan pastinya.',
'Cr_Guide_Q_City' => 'Kurir menolak kota atau alamat',
'Cr_Guide_A_City' => 'Pilih kota dari daftar kota kurir di formulir pemesanan; kurir hanya menerima nama versi mereka sendiri. Kurir yang bekerja dengan alamat pos juga memerlukan provinsi/negara bagian, kode pos, dan kode negara dua huruf.',
'Cr_Guide_Q_Webhook' => 'Status tidak berubah dengan sendirinya',
'Cr_Guide_A_Webhook' => 'Untuk kurir yang mengirim pembaruan, pastikan URL webhook sudah terdaftar di kurir: Log kurir menampilkan setiap pembaruan yang diterima, atau alasan pembaruan ditolak (misalnya secret yang salah). Kurir lainnya diperiksa sesuai jadwal di Pengaturan Kurir, dan Periksa status sekarang langsung menanyakannya.',
'Cr_Guide_Q_Stuck' => 'Pengiriman menampilkan kesalahan pemeriksaan status',
'Cr_Guide_A_Stuck' => 'Kurir menolak pemeriksaan terakhir; alasannya ada pada pengiriman dan di Log kurir. Setelah gagal berulang kali, pengiriman tidak lagi diperiksa otomatis: perbaiki penyebabnya, lalu gunakan Periksa status sekarang.',
'Cr_Guide_Q_Label' => 'Tidak ada yang terbuka saat mencetak label',
'Cr_Guide_A_Label' => 'Browser Anda memblokir pop-up. Izinkan pop-up untuk situs ini dan coba lagi.',
'Cr_Guide_Q_Cod' => 'Pencairan COD tidak tercatat pada penjualan',
'Cr_Guide_A_Cod' => 'Di Pengaturan Kurir, bayar di tempat memerlukan sakelar yang aktif dan akun yang dipilih. Tanpa akun, pencairan hanya ditandai sebagai sudah dicairkan.',
