'Restrict_Master_Data_By_Warehouse' => 'Batasi data master per gudang',
'Restrict_Master_Data_By_Warehouse_Help' => 'Jika aktif, pengguna yang ditugaskan ke gudang tertentu hanya melihat produk, pelanggan, pemasok, merek, dan kategori yang terhubung dengan gudang tersebut. Catatan yang belum pernah digunakan tetap terlihat, sehingga data yang baru dibuat tidak pernah tersembunyi. Penjualan, pembelian, dan retur selalu dibatasi dan tidak terpengaruh oleh sakelar ini.',
'Restrict_Products_By_Warehouse' => 'Batasi produk per gudang',
'Restrict_Products_By_Warehouse_Help' => 'Setiap produk memiliki gudang asal — cabang tempat produk tersebut dibuat. Jika aktif, pengguna yang ditugaskan ke gudang tertentu hanya melihat, menjual, dan mengedit produk yang gudang asalnya adalah gudang mereka, ditambah produk yang memiliki stok nyata di salah satu gudang mereka (hasil transfer atau pembelian). Pengguna yang boleh mengakses semua gudang selalu melihat semuanya. Toko daring mengikuti aturan yang sama: hanya menampilkan produk dari gudang yang dipilih di Pengaturan Toko.',
'Virtual_Combo_Stock' => 'Stok kombo virtual',
'Virtual_Combo_Stock_Help' => 'Jika aktif, produk kombo tidak memiliki stok sendiri: ketersediaannya adalah jumlah kombo yang masih dapat dipenuhi oleh produk komponennya, dan menjual kombo akan mengambil stok dari komponen. Jika nonaktif, kombo dirakit menjadi stok terlebih dahulu dengan Penyesuaian.',
'Virtual_Combo_Stock_Warning' => 'Sebaiknya dipilih sebelum menjual kombo. Setelah kombo terjual atau diretur, mengubah pengaturan ini akan membuat pengeditan, penghapusan, dan retur dokumen tersebut di kemudian hari membalik stoknya ke arah yang salah.',
'Virtual_Combo_Stock_Confirm_On_Title' => 'Aktifkan stok kombo virtual?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'Kombo akan dijual langsung dari produk komponennya, dan stoknya sendiri tidak akan digunakan lagi.',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'Nonaktifkan stok kombo virtual?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'Kombo akan kembali menggunakan stoknya sendiri, yang harus dirakit dari komponen dengan Penyesuaian sebelum dapat dijual.',
'Home_Warehouse' => 'Gudang asal',
'Home_Warehouse_Hint' => 'Cabang pemilik produk ini. Pengguna yang dibatasi ke gudang lain tidak akan melihatnya kecuali stok ditransfer kepada mereka.',
