'Product_Supplier' => 'Pemasok pada produk',
'Product_Supplier_Help' => 'Menambahkan kolom pemasok default ke formulir produk, menampilkannya sebagai kolom di daftar produk, dan memungkinkan Anda memfilter produk menurut pemasok untuk menyusun daftar pemesanan ulang.',
