'Tg_Guide_A_Title' => 'Langsung — tanpa perlu memasang apa pun',
'Tg_Guide_A_Body' => 'Penjualan, pembelian, pembayaran, atau beban yang disimpan di Stocky — di POS atau di panel admin — dikirim ke Telegram {rightAfter} disimpan, dalam permintaan yang sama. Tanpa entri cron, tanpa queue worker, dan kasir tidak pernah menunggu Telegram: penjualan sudah selesai diproses ketika pesan dikirim.',
'Tg_Guide_Right_After' => 'segera setelah',
'Tg_Guide_B_Title' => 'Entri cron — untuk percobaan ulang dan event latar belakang',
'Tg_Guide_B_Body' => 'Dua jenis pesan menunggu di antrean Telegram sendiri: pengiriman yang gagal (Telegram tidak dapat dijangkau sesaat), yang dicoba ulang hingga tiga kali lagi dalam beberapa menit berikutnya; dan event yang muncul di luar panel admin — pesanan yang diimpor dari WooCommerce atau Shopify, perintah artisan. Entri cron ini mengirimkannya, dan tidak melakukan hal lain:',
'Tg_Guide_B_Note' => 'Setiap menit sudah tepat: proses tanpa antrean langsung berhenti. Di cPanel, entri ini dimasukkan ke {cronJobs} — gunakan path lengkap ke PHP 8.2+ jika {php} lebih lama. Di Windows, gunakan Task Scheduler dengan program {php2}, argumen {args}, dimulai di {path}.',
