'Jumia_Hero_Title' => 'Sinkronisasi marketplace Jumia',
'Jumia_Hero_Desc' => 'Kirim harga dan stok ke listing Jumia Seller Center Anda dan impor pesanan marketplace sebagai penjualan.',
