'Jumia_Prices_Stock' => 'Harga & Stok',
'Jumia_Push_Card_Title' => 'Kirim harga & stok ke Jumia',
'Jumia_Push_Desc' => 'Mengirim harga dan jumlah terkini untuk setiap produk (dan varian) yang memiliki SKU sesuai dengan {sellerSku} pada listing Jumia. Pembaruan dikirim sebagai feed Seller Center dan diterapkan secara asinkron — ID feed dicatat di tab Log, dan penolakan per item muncul di layar status feed Seller Center.',
'Jumia_Push_Prices_Stock' => 'Kirim harga & stok',
'Jumia_Orders_Desc' => 'Mengimpor pesanan marketplace sebagai penjualan (referensi seperti {ref}), dicocokkan dengan produk Anda berdasarkan Seller SKU. Pesanan yang sudah diimpor dan yang dibatalkan dilewati, sehingga pengambilan rutin aman dilakukan. Pembayaran ditandai lunas hanya untuk pesanan yang sudah terkirim (Jumia didominasi COD).',
'Jumia_Guide_1' => 'Di Jumia {sellerCenter}, buka Settings → {integrationMgmt} dan buat kunci API.',
'Jumia_Guide_2' => 'Masukkan URL API negara Anda (mis. {ng} untuk Nigeria, {ke} untuk Kenya, {eg} untuk Mesir), email akun Seller Center Anda, dan kuncinya — lalu jalankan {test}.',
'Jumia_Guide_3' => 'Pastikan {sellerSku} pada setiap listing Jumia sama dengan kode produk Stocky — itulah identitas yang digunakan untuk pengiriman stok maupun pencocokan pesanan.',
'Jumia_Guide_4' => 'Kirim harga & stok setelah inventaris berubah; ambil pesanan secara rutin (Jumia tidak memiliki webhook di API ini).',
'Jumia_Guide_5' => 'Pembuatan listing baru tetap dilakukan di Seller Center — Jumia mewajibkan atribut khusus kategori dan peninjauan gambar yang hanya dapat ditangani dengan baik oleh portal mereka.',
'Mc_Hero_Title' => 'Sinkronisasi audiens Mailchimp',
