'Mc_Auto_Sync_New' => 'Sinkronkan otomatis pelanggan baru saat dibuat',
'Mc_With_Email' => 'Dengan email',
'Mc_Push_Desc' => 'Menambahkan atau memperbarui setiap pelanggan yang memiliki alamat email ke audiens yang dipilih (termasuk nama dan telepon). Anggota yang sudah ada mempertahankan status langganannya — tidak ada yang sudah berhenti berlangganan didaftarkan ulang. Pelanggan tanpa email tidak disertakan.',
'Mc_Double_Opt_In_Off' => 'Double opt-in nonaktif',
