'Presta_Key_Placeholder' => 'Dari Advanced Parameters → Webservice',
'Presta_Key_Help' => 'Aktifkan webservice di PrestaShop (Advanced Parameters → Webservice), buat kunci dengan izin pada products, stock_availables, orders, dan customers, lalu tempel di sini. Disimpan dalam mode tulis-saja.',
'Presta_Shop_Language_ID' => 'ID bahasa toko',
'Presta_Language_Help' => 'ID bahasa yang digunakan untuk nama produk saat mengirim (1 = bahasa pertama toko).',
'Presta_Push_Desc' => 'Membuat produk sederhana yang belum ada di PrestaShop (beserta stok terkininya). Produk yang sudah tertaut dan produk varian dilewati — tetap ubah detail produk di PrestaShop, atau ambil untuk memperbarui salinan lokal.',
'Presta_Pull_Desc' => 'Mengimpor produk PrestaShop, mencocokkan produk yang sudah ada berdasarkan reference (SKU) dan membuat sisanya. Kombinasi diimpor sebagai produk induknya.',
'Presta_Reset_Confirm' => 'Atur ulang tautan produk? Riwayat pesanan tetap mempertahankan tautannya.',
'Presta_Stock_Desc' => 'Memperbarui stok toko (stock_availables) untuk setiap produk yang tertaut.',
'Presta_Orders_Desc' => 'Mengimpor pesanan toko sebagai penjualan (referensi seperti {ref}), dari yang terbaru. Pesanan yang sudah diimpor dan yang dibatalkan dilewati, sehingga pengambilan rutin aman dilakukan. PrestaShop tidak memiliki webhook — jalankan ini setelah periode sibuk.',
'Presta_Guide_1' => 'Di back office PrestaShop Anda, buka {path} dan aktifkan webservice.',
