'Presta_Guide_3' => 'Tempel URL toko dan kunci di tab Koneksi, simpan, lalu jalankan {test}.',
'Presta_Guide_4' => 'Ambil produk terlebih dahulu jika toko sudah memiliki katalog (dicocokkan berdasarkan reference/SKU); kirim untuk membuat produk sederhana yang belum ada.',
'Presta_Guide_5' => 'Kirim stok setiap kali jumlah berubah, dan ambil pesanan secara rutin — PrestaShop tidak memiliki webhook, jadi pesanan hanya masuk saat Anda mengambilnya.',
