'Fbr_Token_Saved' => 'Token sudah disimpan (••••{last4}). Kosongkan untuk mempertahankannya.',
'Fbr_Token_Obtain' => 'Dapatkan token dari portal e-invoicing PRAL / IRIS.',
'Fbr_Token_Placeholder' => 'Tempel token dari portal e-invoicing PRAL / IRIS',
'Fbr_Guide_What_Title' => 'Apa itu Faktur Digital FBR?',
'Fbr_Guide_What_Body' => 'Berdasarkan SRO 69(I)/2025, Federal Board of Revenue (Pakistan) mewajibkan bisnis terintegrasi melaporkan faktur penjualan secara elektronik dan real-time melalui API PRAL Digital Invoicing (DI). Setiap penjualan yang diterima mendapatkan nomor faktur FBR resmi, dan struk harus menampilkan nomor tersebut beserta kode QR verifikasi.',
'Fbr_Guide_Steps_Title' => 'Langkah untuk mulai beroperasi',
'Fbr_Guide_Step_1' => 'Daftar di portal e-invoicing FBR IRIS dan dapatkan token keamanan {sandbox}.',
'Fbr_Guide_Step_2' => 'Konfigurasikan profil penjual Anda di tab Konfigurasi (NTN/CNIC, nama usaha, provinsi, alamat), tempel token, lalu aktifkan integrasi dengan lingkungan diatur ke {sandbox}.',
'Fbr_Guide_Step_3' => 'Lakukan penjualan uji yang mencakup skenario yang ditetapkan FBR untuk Anda (pilih skenario di kolom Skenario Sandbox). Periksa tab Dokumen untuk memastikan hasilnya {valid}.',
'Fbr_Guide_Step_4' => 'Setelah FBR menyetujui pengujian sandbox Anda, dapatkan token {production} dari portal, tempel di sini, lalu ubah lingkungan ke {production}.',
'Fbr_Guide_Step_5' => 'Struk otomatis menampilkan nomor faktur FBR dan kode QR setelah penjualan diterima — tidak ada langkah tambahan di kasir.',
'Fbr_Sandbox_Lower' => 'sandbox',
'Fbr_Production_Lower' => 'produksi',
'Fbr_Guide_Note_1' => 'Atur kode HS per produk di formulir produk (kolom "Kode HS"). Kode HS Bawaan yang dikonfigurasi di sini hanya digunakan untuk produk yang belum memilikinya.',
'Fbr_Guide_Note_2' => 'Pelanggan umum yang tidak terdaftar dilaporkan ke FBR sebagai "Unregistered".',
'Fbr_Guide_Note_3' => 'Untuk pembeli terdaftar, masukkan NTN mereka di kolom Nomor pajak pada data pelanggan agar dilaporkan sebagai terdaftar.',
'Fbr_Guide_Note_4' => 'Pengiriman yang gagal atau tidak valid dapat dicoba ulang dari tab Dokumen setelah penyebabnya diperbaiki; tab Log menampilkan pertukaran API mentah untuk pemecahan masalah.',
