'Woo_WordPress_Username' => 'Nama pengguna WordPress',
'Woo_WordPress_App_Password' => 'Application password WordPress',
'Woo_Automatic_Sync' => 'Sinkronisasi otomatis',
'Woo_Auto_Sync_Intro' => 'Kirim perubahan yang dibuat di Stocky ke WooCommerce saat itu juga, tanpa membuka halaman ini. Setiap pengiriman berjalan tepat setelah tindakan disimpan, sehingga kasir tidak perlu menunggu WooCommerce. Hasilnya muncul di tab Log.',
'Woo_Auto_Sync_Products_Help' => 'Produk yang dibuat, diubah, atau diduplikasi di Stocky dikirim ke WooCommerce (detail, harga, varian, gambar, stok). Impor massal tidak dikirim; setelah impor, gunakan Sinkronisasi — POS → WooCommerce di tab Produk.',
'Woo_Auto_Sync_Stock_Help' => 'Setiap pergerakan stok (penjualan POS, penjualan, retur, pembelian, penyesuaian, transfer) memperbarui kuantitas produk terkait di WooCommerce. Hanya produk yang sudah ditautkan ke WooCommerce yang diperbarui.',
'Woo_Sync_Tuning' => 'Penyetelan sinkronisasi',
'Woo_Sync_Tuning_Intro' => 'Nilai bawaan cocok untuk sebagian besar toko. Ubah hanya jika sinkronisasi lambat atau mengalami timeout di hosting Anda. Setiap nilai dibatasi pada rentang yang aman, dan mengosongkan kolom akan mengembalikan nilai bawaannya.',
'Woo_Sync_Guide' => 'Panduan Sinkronisasi WooCommerce',
'Woo_Guide_Getting_Keys' => 'Mendapatkan kunci API',
'Woo_Guide_Keys_1' => 'Di WooCommerce: WooCommerce → Settings → Advanced → REST API.',
'Woo_Guide_Keys_2' => 'Klik Add key, pilih Read/Write, lalu salin Consumer key dan Consumer secret.',
'Woo_Guide_Keys_3' => 'URL Toko: URL situs Anda tanpa garis miring di akhir (mis. {example}).',
'Woo_Guide_WP_Title' => 'Nama Pengguna WP dan Application Password (opsional)',
'Woo_Guide_WP_Intro' => 'Kolom ini hanya digunakan untuk gambar produk. API WooCommerce (URL Toko + Consumer key/secret) menangani sinkronisasi produk, stok, kategori, merek, pelanggan, dan pesanan; WordPress REST API menangani Media Library (mencari dan mengunggah gambar).',
'Woo_Guide_WP_1' => 'Saat menyinkronkan produk atau stok, Stocky dapat melampirkan gambar produk: pertama-tama mencari gambar yang sudah ada di Media Library WordPress berdasarkan nama file; jika tidak ditemukan, gambar diunggah melalui API WordPress.',
'Woo_Guide_WP_2' => 'Gunakan pengguna WordPress yang dapat mengelola media (mis. Administrator). Buat Application Password di WordPress: Users → Profile (atau pengguna Anda) → Application Passwords — tambahkan yang baru lalu tempel di sini.',
'Woo_Guide_WP_3' => 'Jika dibiarkan kosong, sinkronisasi tetap berjalan untuk semua data (produk, stok, kategori, merek, pelanggan, pesanan); hanya pelampiran gambar produk (pencarian/unggah) yang dilewati.',
'Woo_Guide_How_To_Enable' => 'Cara mengaktifkan',
'Woo_Guide_Enable_1' => 'Masukkan URL Toko, Consumer key, dan Consumer secret di atas, lalu klik Simpan.',
'Woo_Guide_Enable_2' => 'Gunakan Uji koneksi untuk memverifikasi kredensial.',
'Woo_Guide_Enable_3' => 'Gunakan sinkronisasi manual dari tab mana pun saat Anda perlu menyinkronkan.',
'Woo_Guide_Enable_4' => 'Aktifkan Sinkronisasi otomatis di atas untuk mengirim produk baru dan yang diubah serta setiap perubahan stok ke WooCommerce saat itu juga.',
'Woo_Guide_Manual_Sync' => 'Sinkronisasi manual (sesuai kebutuhan)',
'Woo_Guide_Manual_1' => 'Sinkronisasi berjalan dua arah: Stocky → WooCommerce dan WooCommerce → Stocky.',
'Woo_Guide_Manual_2' => 'Sinkronisasi manual tersedia di semua tab WooCommerce (Produk, Stok, dll.); gunakan tindakan sinkronisasi di setiap tab untuk menjalankannya sesuai kebutuhan.',
'Woo_Guide_Auto_1' => 'Produk: jika aktif, produk yang Anda buat, ubah, atau duplikasi di Stocky dikirim ke WooCommerce tepat setelah Anda menyimpannya, diikuti stoknya.',
'Woo_Guide_Auto_2' => 'Stok: jika aktif, setiap perubahan stok (penjualan POS, penjualan, retur, pembelian, penyesuaian, transfer) memperbarui kuantitas di WooCommerce. Hanya produk yang sudah ditautkan ke WooCommerce yang diperbarui.',
'Woo_Guide_Auto_3' => 'Sinkronisasi otomatis hanya mengirim perubahan dari Stocky ke WooCommerce. Mengambil data dari WooCommerce ke Stocky (pesanan, pelanggan, produk) selalu dilakukan dengan tombol di tab Pesanan, Pelanggan, dan Produk.',
'Woo_Guide_Auto_4' => 'Impor produk massal tidak dikirim secara otomatis. Setelah impor, gunakan Sinkronisasi — POS → WooCommerce di tab Produk.',
'Woo_Guide_Auto_5' => 'Setiap pengiriman otomatis dicatat di tab Log, sehingga Anda dapat memeriksa apa yang dikirim dan menemukan kesalahan.',
'Woo_Guide_First_Setup' => 'Penyiapan awal',
'Woo_Guide_First_1' => 'Jalankan ini sekali, sesuai urutan berikut, agar katalog yang sudah ada tertaut: Sinkronisasi — POS → WooCommerce di tab Kategori, lalu tab Merek, lalu tab Produk, dan terakhir Sinkronisasi Stok di tab Stok. Setelah itu, aktifkan Sinkronisasi otomatis di atas agar WooCommerce selalu mutakhir.',
'Woo_Guide_First_2' => 'Sinkronisasi produk dan stok dalam jumlah besar berjalan dalam batch kecil dan menampilkan progresnya di tab. Biarkan halaman tetap terbuka hingga sinkronisasi selesai; Anda dapat menghentikannya kapan saja.',
'Woo_Guide_First_3' => 'Jika sinkronisasi tidak bergerak selama beberapa menit, periksa tab Log, lalu hubungi dukungan.',
'Woo_Guide_Notes_1' => 'Mengubah URL Toko atau kunci API akan mereset pemetaan (produk, kategori, merek, pelanggan); item akan disinkronkan ulang ke toko (yang baru).',
'Woo_Guide_Notes_2' => 'Jaga agar SKU tetap konsisten antara Stocky dan WooCommerce untuk menghindari produk ganda dan agar penautan ulang aman.',
