'Shp_G_Realtime_Lead' => 'Setiap perubahan dikirim saat terjadi, dalam hitungan detik. Ada dua bagian, dan keduanya sakelar terpisah: {webhooks} membawa peristiwa toko masuk, dan {push} mengirim stok keluar.',
'Shp_G_Webhooks_Lc' => 'webhook',
'Shp_G_Instant_Push_Lc' => 'pengiriman stok instan',
'Shp_G_Webhooks_Heading' => 'Webhook — toko → ERP',
'Shp_G_Webhooks_Body' => 'Pesanan, perubahan status pesanan, serta perubahan produk, pelanggan, dan stok yang dibuat di Shopify. Buka toko dan tekan {button} di {tab} — aman ditekan dua kali. Shopify mengirim ke:',
'Shp_G_Webhooks_Tab' => 'tab Webhook',
'Shp_G_Webhooks_Note' => 'Alamat harus dapat dijangkau dari internet melalui HTTPS — Shopify tidak akan mengirim ke {localhost} atau domain {test}. Setiap pengiriman dicatat sekali, sehingga percobaan ulang Shopify tidak dapat membuat pesanan ganda, dan pengiriman yang gagal dapat diputar ulang. Pengiriman ditolak sampai rahasia penandatanganan dari langkah 1 disimpan.',
'Shp_G_Push_Heading' => 'Pengiriman stok instan — ERP → toko',
'Shp_G_People_Miss' => 'Inilah pengaturan yang sering terlewat',
'Shp_G_Push_P1' => 'Penjualan POS {not} sampai ke Shopify dengan sendirinya. Jika dibiarkan nonaktif, toko baru mengetahuinya pada langkah kirim Inventaris berikutnya — dan dalam jeda itu toko dapat menjual unit yang sudah Anda jual di kasir.',
'Shp_G_Not' => 'tidak',
'Shp_G_Push_P2' => 'Centang {setting} di {path}. Hanya itu penyiapannya — tanpa worker, tanpa cron. Setiap penjualan, retur, dan penyesuaian kemudian mengirim stok untuk produk terkait saja, tepat setelah penjualan disimpan, dan penjualan dua puluh baris hanya memerlukan satu pengiriman, bukan dua puluh. Kasir tidak pernah menunggunya.',
'Shp_G_This_Store' => 'Toko ini:',
'Shp_G_Push_On' => 'aktif — stok dikirim saat berubah',
'Shp_G_Push_Off' => 'nonaktif — stok hanya sesuai jadwal',
'Shp_G_Push_Note' => 'Hanya produk yang sudah memiliki pemetaan Shopify, dan hanya pergerakan di gudang toko ini, yang dikirim. Operasi massal — menghapus produk, mengatur ulang gudang — menulis stok tanpa memicu peristiwa, yang menjadi salah satu alasan untuk tetap mempertahankan langkah inventaris terjadwal.',
'Shp_G_Nothing_Else' => 'Tidak ada lagi yang perlu dipasang',
'Shp_G_Nothing_Else_Body' => 'Kedua bagian tidak memerlukan queue worker maupun entri cron. Webhook yang masuk ditangani dalam permintaan yang dibuat Shopify; pengiriman stok keluar berjalan dalam proses yang sama yang melayani penjualan, {after} respons dikirim kembali — sehingga kasir tidak pernah menunggu Shopify, dan toko yang berhenti merespons akan ditinggalkan setelah sepuluh detik dan diserahkan ke pengiriman inventaris terjadwal berikutnya.',
'Shp_G_After' => 'setelah',
'Shp_G_Exception' => 'Satu pengecualian: perubahan stok yang dibuat oleh tugas latar belakang tidak memiliki respons untuk ditunggu, sehingga dimasukkan ke antrean {queue}.',
'Shp_G_Queue_Managed' => 'Platform Anda sudah menjalankan worker pada antrean tersebut, jadi pengiriman itu juga berjalan sendiri.',
'Shp_G_Queue_Cron' => 'Jika Anda ingin pengiriman itu juga segera keluar, kosongkan antrean tersebut:',
'Shp_G_On_Schedule' => 'Sesuai jadwal',
'Shp_G_On_Lc' => 'aktif',
'Shp_G_Off_Lc' => 'nonaktif',
'Shp_G_Scheduled_Lead' => 'Semuanya diperiksa ulang secara berkala, ke dua arah. Lebih lambat daripada waktu nyata, tetapi inilah yang mengirim stok keluar pada toko yang tidak menggunakan pengiriman instan, yang menangkap webhook yang terlewat, dan satu-satunya cara memindahkan seluruh katalog.',
'Shp_G_Nothing_To_Install' => 'Tidak ada yang perlu dipasang',
'Shp_G_Managed_Body' => 'Penjadwal dijalankan untuk Anda: setiap lima menit platform Anda menanyakan setiap toko apakah ada langkah dalam rencananya yang sudah waktunya, dan menjalankan langkah tersebut. Tidak ada entri cron yang perlu ditambahkan dan tidak ada server yang perlu dirawat.',
'Shp_G_Managed_Note' => 'Lima menit juga merupakan resolusi terkecil yang dapat digunakan rencana, karena lima menit adalah interval langkah terpendek. Interval yang lebih panjang dipatuhi dengan tepat — langkah yang diatur 30 menit diperiksa enam kali dan berjalan sekali.',
'Shp_G_Cron_Entry' => 'Entri cron',
'Shp_G_Cron_Body' => 'Tidak ada yang terjadwal berjalan tanpanya. Satu baris, khusus modul ini — tambahkan di samping apa pun yang telah Anda jadwalkan:',
'Shp_G_Cron_Note' => 'Setiap lima menit adalah resolusi terkecil yang dapat digunakan rencana, karena lima menit adalah interval langkah terpendek. Entri yang lebih jarang akan menjadi batas bawah — dengan {every15}, langkah yang diatur 5 menit berjalan setiap 15 menit. Di Windows gunakan Task Scheduler: program {php}, argumen {args}, dimulai di {path}.',
'Shp_G_Switch_On' => 'Aktifkan, lalu pilih rencananya',
'Shp_G_Plan_Body' => '{path} Sakelar menentukan apakah penjadwal boleh bertindak sama sekali; rencana menentukan apa yang dilakukannya. Sebuah {step} adalah satu entitas dalam satu arah dengan intervalnya sendiri — {ex1}, {ex2}. Interval bawaan digunakan oleh setiap langkah yang kotak intervalnya dibiarkan kosong.',
'Shp_G_Step_Lc' => 'langkah',
'Shp_G_Ex1' => 'Pesanan · Shopify → ERP setiap 15 menit',
'Shp_G_Ex2' => 'Inventaris · ERP → Shopify setiap 30 menit',
'Shp_G_Plan_Note' => 'Biarkan rencana kosong dan toko akan mengambil pesanan serta mengirim stok pada interval bawaan, yang memang diinginkan sebagian besar toko. Pesanan hanya diambil: Shopify adalah tempat pelanggan membuat pesanan.',
'Shp_G_Schedule_On' => 'jadwal aktif',
'Shp_G_Schedule_Off' => 'jadwal nonaktif — hanya manual',
'Shp_G_When_Runs' => 'Kapan sebuah langkah benar-benar berjalan',
'Shp_G_When_Body' => 'Sebuah langkah jatuh waktunya ketika langkah yang sama terakhir kali {started} sudah lebih lama dari intervalnya, dibaca dari riwayat proses. Jadi sinkronisasi yang Anda mulai secara manual menunda proses otomatis berikutnya, dan langkah yang terus gagal dicoba ulang sesuai intervalnya, bukan setiap detak. Ikhtisar toko menampilkan proses terakhir setiap langkah, waktu jadwal berikutnya, dan alasan langkah tersebut terblokir jika memang terblokir. Jalankan pengiriman katalog pertama secara manual dari Pusat Sinkronisasi — sebagai uji coba terlebih dahulu — sebelum memasukkannya ke jadwal.',
'Shp_G_Started_Lc' => 'dimulai',
'Shp_G_Where_Setting' => 'Letak setiap pengaturan',
'Shp_G_Where_Note' => 'Semua ini ada di toko yang sudah ada: {path}, lalu ikon pensil (atau {edit} di halaman toko itu sendiri).',
'Shp_G_Product_Images' => 'Gambar produk',
'Shp_G_Img1' => 'Gambar dikirim bersama produk pada {push} — gambar utama terlebih dahulu, lalu galeri, lalu satu per varian yang memiliki gambar sendiri, hingga lima puluh.',
'Shp_G_Products_Push' => 'pengiriman produk',
'Shp_G_Img2' => 'Gambar varian diunggah bersama produk lalu {assigned}, sesuai cara Shopify memodelkannya: varian menunjuk ke salah satu gambar produk. Varian yang memakai ulang gambar utama tidak mengunggahnya dua kali.',
'Shp_G_Assigned' => 'ditetapkan ke varian tersebut',
'Shp_G_Img3' => 'Gambar yang disimpan sebagai file {uploaded} ke Shopify, bukan ditautkan, sehingga tetap berfungsi meskipun instalasi ini tidak dapat dijangkau dari internet. Gambar yang ditambahkan sebagai tautan yang ditempel diserahkan ke Shopify sebagai URL tersebut, yang harus dapat dijangkau publik.',
'Shp_G_Uploaded' => 'diunggah',
'Shp_G_Img4' => 'Gambar hanya dikirim ulang jika benar-benar berubah — pengiriman yang hanya mengubah harga tidak menyentuh gambar toko, karena mengirim gambar akan mengganti seluruh set.',
'Shp_G_Img5' => 'Menghapus gambar di ERP {not} menghapusnya di Shopify. Hapus juga di sana, atau toko akan terus menampilkannya.',
'Shp_G_Commands' => 'Perintah yang perlu diketahui',
'Shp_G_Command_Copied' => 'Perintah disalin',
'Shp_G_Foot' => 'Setiap sinkronisasi menulis ke {logs}, dan Ikhtisar setiap toko menampilkan kapan setiap langkah terakhir berjalan, kapan jadwal berikutnya, dan apa yang memblokirnya jika ada. Di situlah tempat pertama untuk diperiksa ketika sinkronisasi tidak berjalan sesuai harapan.',
'Shp_G_Covers' => 'Cakupan',
'Shp_G_Speed' => 'Kecepatan',
'Shp_G_Needs' => 'Kebutuhan',
'Shp_G_Switched_On_At' => 'Diaktifkan di',
'Shp_G_Way_Covers_Rt' => 'Pesanan dan perubahan yang dibuat di Shopify; stok yang keluar dari ERP (penjualan POS, retur, penyesuaian)',
'Shp_G_Way_Covers_Sc' => 'Semuanya, ke dua arah — termasuk pengiriman katalog dan apa pun yang terlewat oleh jalur cepat',
'Shp_G_Seconds' => 'Detik',
