'Agt_Correct' => 'Koreksi',
'Agt_Guide_What_Title' => 'Fungsi fitur ini',
'Agt_Guide_What_Body' => 'Setiap penjualan yang selesai diterbitkan sebagai faktur elektronik AGT (FR jika dibayar saat dibuat, selain itu FT) dan setiap retur yang diterima sebagai nota kredit (NC). Setiap dokumen mendapatkan nomor berikutnya dari seri AGT-nya, ditandatangani dengan kunci AGT Anda, lalu dikirim ke AGT, yang memvalidasinya beberapa menit kemudian. Struk dan faktur PDF mencetak nomor AGT, ekstrak keamanan, dan kode QR.',
'Agt_Guide_Steps_Title' => 'Penyiapan',
'Agt_Guide_Step_1' => 'Daftar e-invoicing (adesão) di Portal do Contribuinte dan unduh kunci privat AGT Anda.',
'Agt_Guide_Step_2' => 'Masukkan NIF, tempat usaha, dan kunci di tab Konfigurasi, pilih Homologação, simpan, lalu gunakan Uji koneksi.',
'Agt_Guide_Step_3' => 'Di tab Seri, ajukan satu seri per jenis dokumen yang Anda gunakan (FR, FT, NC) untuk tahun berjalan.',
'Agt_Guide_Step_4' => 'Petakan tarif IVA Anda ke kode AGT dan atur kode pembebasan untuk baris 0%.',
'Agt_Guide_Step_5' => 'Aktifkan modul di Pengaturan Sistem > Fitur, buat penjualan uji, lalu periksa bahwa penjualan itu menjadi valid di tab Dokumen.',
'Agt_Guide_Step_6' => 'Setelah AGT menyetujui Anda untuk produksi, beralihlah ke Produção dan ajukan seri produksi.',
'Agt_Guide_Note_1' => 'Penjualan atau retur yang sudah dikomunikasikan tidak dapat lagi diedit atau dihapus. Koreksi dengan retur penjualan (nota kredit).',
'Agt_Guide_Note_2' => 'Dokumen yang ditolak AGT dikoreksi dengan nomor baru yang merujuk ke dokumen yang ditolak; nomor lama tidak pernah dipakai ulang.',
'Agt_Guide_Note_3' => 'Penjualan POS offline dikomunikasikan saat disinkronkan. AGT mengenakan sanksi untuk dokumen yang dikirim terlambat lebih dari 24 jam.',
'Agt_Guide_Note_4' => 'Satu baris tidak dapat memuat pajak produk sekaligus pajak pesanan; AGT memerlukan satu tarif IVA per baris. Ongkos kirim dikirim sebagai baris bebas pajak.',
'Agt_Guide_Note_5' => 'Total AGT dihitung per baris dan dapat berbeda beberapa sen dari total Stocky karena pembulatan.',
