'Comm_G_F_Program_To' => 'Penjualan bertanggal setelah hari ini diabaikan oleh program. Biarkan kosong untuk program yang tidak pernah berakhir.',
'Comm_G_T_Agents' => 'Agen penjualan',
'Comm_G_Agents_Body' => 'Agen penjualan adalah orang yang mendapatkan komisi. Agen tidak harus menjadi pengguna sistem: perujuk atau reseller dari luar juga dapat menjadi agen, dan mereka mendapat komisi setiap kali dipilih pada penjualan.',
'Comm_G_F_Agent_Name' => 'Nama yang ditampilkan pada penjualan, laporan, dan tanda terima.',
'Comm_G_F_Agent_Code' => 'Referensi opsional seperti nomor karyawan. Dapat dicari di daftar agen.',
'Comm_G_F_Agent_User' => 'Menautkan agen ke pengguna staf. Penjualan yang dibuat pengguna itu (atau yang memilihnya sebagai penjual di POS) kemudian otomatis dikreditkan ke agen ini.',
'Comm_G_F_Agent_Active' => 'Agen nonaktif tidak mendapat komisi dari penjualan baru dan tidak muncul di pilihan agen. Komisi lamanya tetap ada.',
'Comm_G_T_Rules' => 'Aturan komisi: penjelasan setiap kolom',
'Comm_G_Rules_Body' => 'Aturan menentukan berapa yang dibayarkan atas suatu penjualan. Gunakan kotak "Coba aturan" di atas untuk memeriksa aturan sebelum Anda menyimpannya.',
'Comm_G_F_Rule_Program' => 'Program tempat aturan ini berada. Aturan hanya berlaku selama program tersebut aktif dan dalam rentang tanggalnya.',
'Comm_G_F_Rule_Type' => 'Persentase membayar bagian dari jumlah dasar. Tetap membayar jumlah yang sama untuk setiap penjualan yang memenuhi syarat, berapa pun besarnya.',
'Comm_G_F_Rule_Source' => 'Dasar pengambilan persentase. Total Penjualan adalah total akhir penjualan. Jumlah Dibayar adalah jumlah yang telah dibayar pelanggan saat komisi dihitung.',
'Comm_G_F_Rule_Value' => 'Persentase (5 berarti 5%) atau jumlah tetap, tergantung Jenis.',
'Comm_G_F_Rule_Min' => 'Opsional. Penjualan dengan jumlah dasar di bawah nilai ini tidak mendapat komisi dari aturan ini. Penjualan yang tepat sama dengan batas tetap mendapat komisi.',
'Comm_G_F_Rule_Cap' => 'Opsional. Jumlah terbesar yang dapat dibayarkan aturan ini untuk satu penjualan. Berlaku untuk aturan persentase maupun tetap.',
'Comm_G_F_Rule_Applies' => 'Semua Agen: setiap agen mendapat komisi dari aturan ini. Agen Tertentu: hanya agen yang Anda pilih. Aturan Agen Tertentu tanpa agen yang dipilih tidak pernah membayar siapa pun.',
'Comm_G_F_Rule_Priority' => 'Dalam program yang diatur ke "Hanya aturan prioritas tertinggi yang dibayar", aturan memenuhi syarat dengan angka tertinggi yang menang dan yang lain dilewati. Jika seri, aturan Agen Tertentu mengalahkan aturan Semua Agen. Dalam program yang diatur ke "Setiap aturan yang cocok dibayar", Prioritas hanya menentukan urutan.',
'Comm_G_F_Rule_Active' => 'Hapus centangnya untuk menjeda aturan ini saja. Komisi yang sudah dibuatnya tidak terpengaruh.',
'Comm_G_T_Stacking' => 'Beberapa aturan pada satu penjualan',
'Comm_G_Stacking_Body' => 'Setiap program menentukan cara aturannya digabungkan (pengaturan "Jika beberapa aturan cocok" pada program).

Hanya aturan prioritas tertinggi yang dibayar (default untuk program baru): aturan dicoba dari Prioritas tertinggi ke bawah, dan aturan pertama yang memenuhi syarat untuk penjualan itulah yang dibayar. Aturan memenuhi syarat jika penjualan mencapai batas minimumnya dan hasilnya di atas 0. Ini memudahkan pembuatan tingkatan: "7% untuk penjualan 10,000 atau lebih" pada prioritas 10 dan "5%" pada prioritas 0. Untuk memberi Sara tarif khusus, tambahkan aturan Agen Tertentu untuknya dengan prioritas lebih tinggi daripada aturan Semua Agen.

Setiap aturan yang cocok dibayar: semua aturan yang cocok membayar dan jumlahnya dijumlahkan. Aturan Semua Agen sebesar 3% ditambah aturan Agen Tertentu sebesar 2% untuk Sara memberi Sara 5%.

Program terpisah satu sama lain: setiap program aktif membayar sendiri-sendiri, sehingga satu penjualan dapat menghasilkan komisi dari program dasar dan program kampanye sekaligus.',
'Comm_G_T_Paying' => 'Membayar agen dengan Tanda Terima Komisi',
'Comm_G_Paying_Body' => 'Buka Tanda Terima Komisi lalu klik Tambah. Pilih agen: komisi Disetujui miliknya akan ditampilkan. Centang komisi yang Anda bayar; Jumlah terisi dengan totalnya, dan Anda dapat menyesuaikannya. Referensi diisi otomatis (CR-000001, CR-000002...), dan Anda dapat menambahkan metode pembayaran, tanggal, dan catatan.

Menyimpan tanda terima menandai komisi yang dicentang sebagai Dibayar dan menautkannya ke tanda terima. Hanya komisi Disetujui yang dapat dibayar, jadi setujui terlebih dahulu di Laporan Komisi.

Penyesuaian negatif (kelebihan bayar kepada agen) juga ditampilkan. Centang bersama komisi agen berikutnya agar dipotong dari pembayaran tersebut.

Tanda terima hanyalah catatan pembayaran: tanda terima tidak membuat beban atau memindahkan uang di akun Anda. Jika Anda mencatat pembayaran di Beban atau Akuntansi, catat juga di sana.',
'Comm_G_T_Snapshot' => 'Saat penjualan berubah',
'Comm_G_Snapshot_Body' => 'Komisi mengikuti penjualan. Setiap kali penjualan yang memiliki komisi berubah, komisinya dihitung ulang dari angka terkininya: total penjualan dikurangi retur yang diterima, dan jumlah dibayar dikurangi pengembalian dana.

Komisi yang belum dibayar (Tertunda atau Disetujui) cukup diperbarui. Komisi Disetujui yang jumlahnya berubah kembali ke Tertunda agar diperiksa lagi. Komisi yang tidak lagi terutang (penjualan dihapus, diretur seluruhnya, agen diganti) dihapus.

Komisi yang sudah dibayar tidak pernah diubah. Selisihnya menjadi baris Tertunda baru bertanda Penyesuaian: positif jika ada kekurangan bayar (misalnya sisa penjualan Jumlah Dibayar telah dilunasi), negatif jika agen kelebihan bayar (misalnya setelah retur). Setujui lalu masukkan ke tanda terima agen berikutnya.

Setiap komisi menyimpan ketentuan aturan (jenis, tarif, batas, plafon) saat pertama kali diperoleh. Mengubah atau menonaktifkan aturan kemudian tidak mengubah nilai penjualan lama saat dihitung ulang.',
'Comm_G_T_Permissions' => 'Siapa dapat melakukan apa',
'Comm_G_Permission' => 'Izin',
'Comm_G_Lets_You' => 'Yang diizinkan',
'Comm_G_P_View' => 'Melihat semua halaman Komisi: program, agen, aturan, tanda terima, laporan, dan panduan ini.',
'Comm_G_P_Add' => 'Membuat program, agen, dan aturan, serta mencatat Tanda Terima Komisi (membayar agen).',
'Comm_G_P_Edit' => 'Mengedit program, agen, dan aturan, serta menyetujui atau membatalkan komisi di Laporan Komisi.',
'Comm_G_P_Delete' => 'Menghapus program, agen, dan aturan.',
'Comm_G_T_Faq' => 'Tanya jawab',
'Comm_G_Q_Empty' => 'Saya sudah menyiapkan semuanya, tetapi Laporan Komisi kosong.',
'Comm_G_A_Empty' => 'Periksa bahwa: penjualan disimpan setelah aturan dibuat; penjualan berstatus Selesai; penjualan memiliki agen (dipilih pada penjualan, atau pengguna yang membuatnya tertaut ke agen); program aktif dan tanggal penjualan berada dalam rentang tanggalnya; aturan aktif dan berlaku untuk agen tersebut; dan penjualan mencapai atau melebihi batas minimum aturan. Periksa juga filter tanggal laporan: filter itu menyaring berdasarkan tanggal komisi dihitung.',
'Comm_G_Q_Twice' => 'Seorang agen mendapat dua komisi untuk satu penjualan.',
'Comm_G_A_Twice' => 'Dua aturan membayar: program diatur ke "Setiap aturan yang cocok dibayar", atau aturan-aturan itu berada di dua program aktif yang berbeda (setiap program membayar sendiri-sendiri). Atur program ke "Hanya aturan prioritas tertinggi yang dibayar" jika hanya satu yang boleh membayar. Menyimpan penjualan lagi tidak pernah menggandakan komisi.',
'Comm_G_Q_Rate' => 'Jika saya mengubah tarif aturan, apakah komisi lama ikut berubah?',
'Comm_G_A_Rate' => 'Tidak. Setiap komisi menyimpan ketentuan aturan saat komisi itu diperoleh, bahkan saat penjualannya dihitung ulang kemudian. Tarif baru digunakan untuk komisi yang diperoleh mulai sekarang.',
'Comm_G_Q_Return' => 'Pelanggan meretur barangnya. Apa yang terjadi pada komisi?',
'Comm_G_A_Return' => 'Komisi dikurangi secara otomatis. Retur yang diterima menurunkan total penjualan dan pengembalian dana menurunkan jumlah dibayar. Jika komisi belum dibayar, komisi diperbarui (atau dihapus untuk retur penuh). Jika sudah dibayar, Penyesuaian negatif ditambahkan dan dipotong dari tanda terima agen berikutnya.',
'Comm_G_Q_Wrong_Agent' => 'Saya mengkreditkan ke agen yang salah. Bagaimana cara memperbaikinya?',
'Comm_G_A_Wrong_Agent' => 'Edit penjualan, pilih Agen Penjualan yang benar, lalu simpan. Komisi berpindah ke agen yang benar. Jika agen pertama sudah dibayar, Penyesuaian negatif ditambahkan untuknya.',
'Comm_G_Q_Inactive' => 'Apa yang terjadi jika saya menonaktifkan agen?',
'Comm_G_A_Inactive' => 'Agen tidak lagi mendapat komisi dari penjualan baru dan disembunyikan dari pilihan agen. Komisi yang sudah ada tetap ada, masih dapat disetujui dan dibayar, dan tetap mengikuti perubahan penjualannya. Penjualan yang disimpan dengan agen tersebut sebagai pilihan tidak akan beralih ke agen lain.',
'Comm_G_Q_Partial' => 'Bagaimana aturan Jumlah Dibayar menangani pembayaran sebagian?',
'Comm_G_A_Partial' => 'Penjualan yang belum dibayar tidak menghasilkan komisi. Komisi dibuat saat uang pertama kali diterima (saat checkout atau saat pembayaran ditambahkan) dan bertambah seiring masuknya pembayaran berikutnya. Jika sebagian sudah dibayar, sisanya muncul sebagai Penyesuaian positif.',
'Comm_G_Q_Undo' => 'Bisakah saya membatalkan pembayaran atau pembatalan?',
'Comm_G_A_Undo' => 'Pembayaran, tidak: Dibayar bersifat final dan tanda terima tidak dapat diedit atau dihapus, jadi periksa komisi yang dicentang dan jumlahnya sebelum menyimpan. Pembatalan, ya: centang barisnya di Laporan Komisi lalu klik Hitung Ulang, atau simpan kembali penjualan di Edit Penjualan.',
'Comm_G_Q_Dates' => 'Tanggal mana yang digunakan untuk tanggal program?',
'Comm_G_A_Dates' => 'Tanggal penjualan itu sendiri, bukan hari penjualan disimpan. Penjualan bertanggal bulan lalu hanya menggunakan program yang berlaku bulan lalu.',
'Comm_G_When_Changes' => 'Setelah itu, setiap perubahan pada penjualan yang sudah memiliki komisi akan memperbarui komisinya secara otomatis: pembayaran diedit atau dihapus, retur dan pengembalian dana, status tidak lagi Selesai, atau penjualan dihapus.',
'Comm_G_F_Program_Mode' => 'Apa yang terjadi jika beberapa aturan dalam program ini cocok dengan penjualan yang sama. "Hanya aturan prioritas tertinggi yang dibayar": aturan dicoba dari Prioritas tertinggi ke bawah dan aturan pertama yang memenuhi syarat yang dibayar. "Setiap aturan yang cocok dibayar": semuanya membayar dan jumlahnya dijumlahkan.',
'Comm_G_Q_Mode_Old' => 'Saya sudah mengatur prioritas, tetapi aturan tetap dijumlahkan.',
'Comm_G_A_Mode_Old' => 'Program tersebut diatur ke "Setiap aturan yang cocok dibayar". Program yang dibuat sebelum pengaturan ini ada mempertahankan perilaku tersebut agar pembayarannya tidak berubah. Edit program lalu pilih "Hanya aturan prioritas tertinggi yang dibayar".',
'Comm_G_Q_Negative' => 'Mengapa ada komisi negatif?',
'Comm_G_A_Negative' => 'Itu adalah Penyesuaian: agen dibayar lebih dari yang sekarang dihasilkan penjualan, karena retur, pengembalian dana, total yang lebih rendah, agen yang diganti, atau penjualan yang dihapus. Setujui lalu centang di tanda terima agen berikutnya agar dipotong.',
'Comm_Rule_Mode' => 'Jika beberapa aturan cocok',
'Comm_Mode_Highest' => 'Hanya aturan prioritas tertinggi yang dibayar',
'Comm_Mode_All' => 'Setiap aturan yang cocok dibayar (dijumlahkan)',
'Comm_Mode_Highest_Short' => 'Prioritas tertinggi menang',
'Comm_Mode_All_Short' => 'Aturan dijumlahkan',
'Comm_Mode_Highest_Help' => 'Aturan dicoba dari Prioritas tertinggi ke bawah; aturan pertama yang memenuhi syarat untuk penjualan yang dibayar dan yang lain dilewati. Cocok untuk tingkatan, misalnya 7% di atas 10,000 pada prioritas 10 dan 5% untuk semua lainnya pada prioritas 0.',
'Comm_Mode_All_Help' => 'Setiap aturan yang cocok dengan agen membayar atas penjualan, sehingga jumlahnya dijumlahkan. Prioritas hanya menentukan urutan.',
'Comm_Priority_Help_Highest' => 'Program ini hanya membayar aturan prioritas tertinggi yang memenuhi syarat. Beri aturan ini Prioritas lebih tinggi daripada aturan yang harus dikalahkannya. Jika seri, aturan Agen Tertentu mengalahkan aturan Semua Agen.',
'Comm_Priority_Help_All' => 'Program ini membayar setiap aturan yang cocok, sehingga aturan ini ditambahkan ke aturan lainnya. Prioritas hanya menentukan urutan.',
'Comm_Recalculate' => 'Hitung Ulang',
'Comm_Recalculate_Help' => 'Menghitung ulang penjualan dari baris yang dicentang berdasarkan angka terkininya, termasuk komisi yang telah dibatalkan.',
'Comm_Adjustment' => 'Penyesuaian',
'Comm_Adjustment_Help' => 'Koreksi atas komisi yang sudah dibayar, karena penjualan berubah sesudahnya. Jumlah negatif dipotong dari tanda terima agen berikutnya.',
'Comm_Cancel_Confirm' => 'Batalkan komisi yang dipilih?',
'Comm_Cancel_Confirm_Help' => 'Komisi tersebut tidak akan dibayar, dan tetap dibatalkan meskipun ada pembayaran atau retur yang masuk kemudian. Menyimpan penjualan di Edit Penjualan atau mengklik Hitung Ulang akan menghitungnya kembali.',
'Fashion_Tiles_Hint' => 'Tambahkan ubin Anda sendiri (gambar, judul, dan tautan) untuk menggantikan ubin kategori otomatis.',

