// Restaurant Management — phase 1 (foundation)
'Restaurant_Management' => 'Manajemen Restoran',
'Mod_Restaurant_Desc' => 'Denah lantai dan meja, pesanan pelayan, tiket dapur, tambahan (add-on), tagihan, pembayaran terpisah, dan tip.',
