'Rst_Guide_Kitchen_2' => 'Tiket berubah kuning lalu merah selama menunggu (Pengaturan Restoran › terlambat setelah N menit). Bunyi bip menandai tiket baru.',
'Rst_Guide_Kitchen_3' => 'Mulai → centang hidangan → Selesai. "Selesai di stasiun ini" hanya menyelesaikan hidangan stasiun ini pada tiket bersama.',
'Rst_Guide_Kitchen_4' => 'Tiket yang sudah disajikan tetap tampil 15 menit agar kesalahan dapat dipanggil kembali. Tiket dapat dicetak pada printer 80 mm.',
'Rst_Guide_Kitchen_5' => 'Pesanan dari toko daring dan dari kode QR meja ditandai "Daring" atau "QR" pada tiketnya.',
'Rst_Guide_Bills' => 'Tagihan dan pembayaran',
'Rst_Guide_Bills_1' => 'Setiap pembayaran adalah penjualan POS biasa: stok, kas register, akuntansi, poin loyalitas, dan e-invoicing bekerja seperti di POS.',
'Rst_Guide_Bills_2' => 'Biaya layanan adalah persentase dari hidangan sebelum pajak, untuk makan di tempat (atau setiap pesanan, sesuai pengaturan Anda). Tip berupa persentase yang sudah ditentukan atau sejumlah nominal.',
'Rst_Guide_Bills_3' => 'Diskon memerlukan izin "Diskon restoran" dan dibatasi oleh diskon terbesar di Pengaturan Restoran.',
'Rst_Guide_Bills_4' => 'Pembulatan ke bawah sesuai kelipatan Anda, menguntungkan tamu, pada pembayaran yang melunasi tagihan.',
'Rst_Guide_Bills_5' => 'Bagi rata: satu penjualan, satu baris pembayaran per orang (dibagi hingga sen). Bagi per item: hidangan setiap tamu menjadi penjualan tersendiri; pilih kursi untuk memilih hidangannya.',
'Rst_Guide_Bills_6' => 'Jika tagihan berubah setelah ditampilkan (hidangan ditambahkan dari kode QR, tip diubah), pembayaran ditolak agar tamu tidak pernah ditagih untuk sesuatu yang tidak mereka lihat.',
'Rst_Guide_Bills_7' => 'Hidangan yang sudah dibayar tidak dapat dibatalkan. Jika sisa pesanan yang belum dibayar dibatalkan, pesanan ditutup sebagai lunas dan meja dapat dibersihkan.',
'Rst_Guide_Bookings' => 'Reservasi dan daftar tunggu',
'Rst_Guide_Bookings_1' => 'Reservasi menahan meja selama durasinya (default di Pengaturan Restoran). Dua reservasi tidak pernah bisa tumpang tindih pada satu meja.',
'Rst_Guide_Bookings_2' => 'Denah meja menampilkan reservasi berikutnya untuk setiap meja dan memperingatkan saat waktunya sudah dekat; "Sudah datang — tempatkan" menempatkan rombongan.',
'Rst_Guide_Bookings_3' => 'Setelah batas waktu tidak datang, rombongan yang terlambat dapat ditandai tidak datang; kesalahan dapat dipulihkan.',
'Rst_Guide_Bookings_4' => 'Daftar tunggu menyimpan urutan tamu tanpa reservasi beserta perkiraan waktu tunggunya. Telepon atau kirim WhatsApp saat meja siap, lalu tempatkan mereka.',
'Rst_Guide_Bookings_5' => 'Reservasi daring masuk sebagai "Dipesan" (lencana di sidebar menghitungnya) untuk Anda konfirmasi.',
'Rst_Guide_Online' => 'Pesanan daring, menu QR, dan reservasi daring',
'Rst_Guide_Online_1' => 'Dengan tema toko Restoran, beranda toko daring adalah menu Anda, dengan tambahan dan filter diet; pembeli membayar saat checkout seperti biasa.',
'Rst_Guide_Online_2' => '"Pesanan daring ke dapur" menentukan kapan pesanan masuk ke tampilan dapur: saat dibuat (sudah dibayar, atau pelanggan yang sudah login membayar saat pengantaran / pengambilan), saat diterima, atau tidak pernah.',
'Rst_Guide_Online_3' => 'Kode QR meja (Pengaturan denah › Kode QR meja) membuka menu untuk meja tersebut. "Tautan baru" menonaktifkan kode yang sudah dicetak.',
'Rst_Guide_Online_4' => 'Pesanan QR menunggu di pesanan meja sampai pelayan mengirimnya, kecuali "Kirim pesanan QR langsung ke dapur" aktif. Tamu membayar melalui staf.',
'Rst_Guide_Online_5' => 'Reservasi daring hanya menawarkan jam saat ada meja yang muat untuk rombongan dan kosong selama seluruh reservasi, serta membatasi setiap nomor telepon hingga 3 reservasi mendatang.',
'Rst_Guide_Online_6' => 'Semua ini merupakan bagian dari toko daring: toko harus diaktifkan dan termasuk dalam paket Anda.',
'Rst_Guide_Reports' => 'Dasbor dan laporan',
'Rst_Guide_Reports_1' => 'Dasbor membandingkan hari ini dengan hari yang sama minggu lalu: penjualan, tagihan, tamu, rata-rata tagihan, pembatalan, dan diskon, ditambah apa yang sedang terjadi saat ini.',
'Rst_Guide_Reports_2' => 'Penjualan adalah tagihan restoran ditambah pesanan daring yang sudah masuk ke dapur. Penjualan dan margin hidangan dihitung sebelum pajak, memakai biaya setiap produk.',
'Rst_Guide_Reports_3' => 'Laporan: penjualan per hari dan metode pembayaran, hidangan, pembatalan item dan pesanan (beserta alasannya), staf, waktu dapur, dan reservasi — masing-masing dapat diekspor ke Excel.',
'Rst_Guide_Reports_4' => 'Staf yang dibatasi pada cabang tertentu hanya melihat cabangnya; pesanan tanpa cabang dibagikan ke semua.',
'Rst_Guide_Faq' => 'Perlu diketahui',
'Rst_Guide_Faq_1_Q' => 'Pesanan bawa pulang sudah dibayar sebelum saya menekan "Kirim". Apakah akan dimasak?',
'Rst_Guide_Faq_1_A' => 'Ya. Pembayaran akan mengirim ke dapur semua hidangan yang belum dikirim.',
'Rst_Guide_Faq_2_Q' => 'Mengapa saya tidak bisa membersihkan meja?',
'Rst_Guide_Faq_2_A' => 'Pesanannya masih memiliki hidangan yang belum dibayar. Terima pembayarannya, batalkan yang tidak dimakan, atau batalkan pesanan (hanya jika belum ada yang dibayar).',
'Rst_Guide_Faq_3_Q' => 'Dua meja digabungkan. Apa yang terjadi pada pesanannya?',
'Rst_Guide_Faq_3_A' => '"Gabungkan meja" memindahkan hidangan meja kedua (beserta pembayarannya) ke pesanan meja utama; "Pisahkan meja" memisahkan meja kembali.',
'Rst_Guide_Faq_4_Q' => 'Bisakah pembayaran kartu memakai Stripe di sini?',
'Rst_Guide_Faq_4_A' => 'Tidak. Pembayaran kartu Stripe memerlukan formulir kartu POS; untuk terminal kartu, tambahkan metode pembayaran seperti "Kartu" dan gunakan itu pada tagihan.',
'Rst_Guide_Faq_5_Q' => 'Sebuah hidangan kehabisan stok hanya di satu cabang.',
'Rst_Guide_Faq_5_A' => 'Stok diambil dari cabang pesanan (area meja, atau cabang default di Pengaturan Restoran). Gunakan "Habis hari ini" untuk menghentikan pesanan dengan cepat.',
'Rst_Guide_Faq_6_Q' => 'Apakah saya memerlukan printer?',
'Rst_Guide_Faq_6_A' => 'Tidak. Tagihan, struk, dan tiket dapur dicetak dari browser ke printer apa pun; printer struk 80 mm paling sesuai.',
'Rst_Guide_Faq_7_Q' => 'Dari mana menu restoran di toko daring berasal?',
'Rst_Guide_Faq_7_A' => 'Dari produk, kategori, dan tambahan yang sama. Produk yang disembunyikan dari toko daring, dan kategori yang tidak ditampilkan di toko, tidak muncul di menu daring maupun menu QR.',

