'Bkm_Guide_Day_4' => 'Selesaikan tanpa menagih jika sudah dibayar dengan cara lain.',
'Bkm_Guide_Day_5' => 'Tandai tidak datang setelah waktu mulai lewat.',
'Bkm_Guide_Day_6' => 'Dasbor menampilkan jadwal hari ini, apa yang akan datang, dan apa yang belum ditagih.',
'Bkm_Guide_Deposits' => 'Uang muka',
'Bkm_Guide_Deposits_1' => 'Atur jumlahnya di Pengaturan pemesanan › Uang muka; layanan dapat memiliki uang muka sendiri.',
'Bkm_Guide_Deposits_2' => 'Pelanggan membayar dengan penyedia pembayaran yang diatur di Toko daring › Payment Gateway, dalam mata uang dasar Anda.',
'Bkm_Guide_Deposits_3' => 'Waktunya ditahan selama pembayaran; pemesanan yang belum dibayar dapat dibatalkan secara otomatis.',
'Bkm_Guide_Deposits_4' => 'Pembayaran yang berhasil tanpa pelanggan kembali ke situs tetap tercatat secara otomatis.',
'Bkm_Guide_Deposits_5' => 'Saat Anda menagih pemesanan, uang muka menjadi pembayaran pertama pada penjualan.',
'Bkm_Guide_Deposits_6' => 'Pengembalian dana dilakukan di penyedia pembayaran Anda; lalu tandai uang muka sebagai dikembalikan pada pemesanan.',
'Bkm_Guide_Messages' => 'Email, WhatsApp, dan pengingat',
'Bkm_Guide_Messages_1' => 'Pelanggan menerima email saat pemesanan mereka diterima, dikonfirmasi, ditolak, diubah, atau dibatalkan.',
'Bkm_Guide_Messages_2' => 'Anda menerima email untuk setiap pemesanan baru dari situs web, pembatalan oleh pelanggan, dan uang muka yang dibayar.',
'Bkm_Guide_Messages_3' => 'Pengingat dikirim sebelum setiap kunjungan yang dikonfirmasi (Pengaturan pemesanan › Notifikasi).',
'Bkm_Guide_Messages_4' => 'Aktifkan "Kirim juga lewat WhatsApp" untuk mengirim pesan yang sama ke sana.',
'Bkm_Guide_Messages_5' => 'Setiap pesan tercantum pada pemesanan, beserta alasannya jika tidak terkirim.',
'Bkm_Guide_Customers' => 'Pelanggan, CRM, dan portal',
'Bkm_Guide_Customers_1' => 'Pemesanan dari situs web ditambahkan ke daftar pelanggan Anda; orang yang memesan lagi dengan email dan telepon yang sama akan dicocokkan.',
'Bkm_Guide_Customers_2' => 'Jika paket Anda mencakup CRM, pemesanan dapat dicatat pada pelanggan atau prospeknya, dan permintaan dapat membuka peluang.',
'Bkm_Guide_Customers_3' => 'Pelanggan dengan akun portal klien melihat pemesanan mereka di sana dan dapat membatalkan atau menanggapi waktu yang disarankan.',
'Bkm_Guide_Customers_4' => 'Pelanggan toko yang sudah masuk menemukan pemesanan mereka di Akun saya.',
'Bkm_Guide_Roles' => 'Siapa dapat melakukan apa',
'Bkm_Guide_Roles_Help' => 'Berikan setiap peran hanya izin yang diperlukannya (Pengaturan › Izin grup).',
'Bkm_Guide_Job' => 'Pekerjaan',
'Bkm_Guide_Give' => 'Berikan izin',
'Bkm_Guide_Job_Front_Desk' => 'Resepsionis',
'Bkm_Guide_Job_Staff_Member' => 'Anggota staf',
'Bkm_Guide_Job_Manager' => 'Manajer',
'Bkm_Guide_Job_Owner' => 'Pemilik atau akuntan',
'Bkm_Guide_Faq' => 'Pertanyaan',
'Bkm_Guide_Faq_1_Q' => 'Mengapa layanan tidak tampil di situs web?',
'Bkm_Guide_Faq_1_A' => 'Layanan memerlukan detail pemesanan (Layanan), "Tampilkan di situs web" aktif, produk aktif, dan — untuk memilih waktu — seseorang yang dapat dipesan daring yang mengerjakannya.',
'Bkm_Guide_Faq_2_Q' => 'Mengapa tidak ada waktu kosong?',
'Bkm_Guide_Faq_2_A' => 'Periksa jam kerja staf, hari libur, hari libur perusahaan, dan cuti yang disetujui, waktu pemberitahuan minimum, serta berapa hari ke depan pelanggan dapat memesan.',
'Bkm_Guide_Faq_3_Q' => 'Dapatkah dua pelanggan mengambil waktu yang sama?',
'Bkm_Guide_Faq_3_A' => 'Tidak. Waktu diperiksa lagi saat mereka memesan, dan pemesanan yang ditahan atau dikonfirmasi memblokirnya. Kelas berbagi kursi hingga batasnya.',
'Bkm_Guide_Faq_4_Q' => 'Apa yang terjadi saat waktu tahan habis?',
'Bkm_Guide_Faq_4_A' => 'Waktu tersebut kembali kosong untuk orang lain. Pemesanan tetap ada di Permintaan sampai Anda menanggapinya (atau dibatalkan jika uang mukanya tidak dibayar).',
'Bkm_Guide_Faq_5_Q' => 'Apakah pelanggan memerlukan akun?',
'Bkm_Guide_Faq_5_A' => 'Tidak. Mereka mendapatkan tautan pribadi ke halaman pemesanan mereka. Akun toko dan portal juga menampilkan pemesanan mereka.',
'Bkm_Guide_Faq_6_Q' => 'Ke mana uangnya masuk?',
'Bkm_Guide_Faq_6_A' => 'Uang muka masuk ke penyedia pembayaran Anda; sisanya diterima di POS saat Anda menagih pemesanan. Laporan menghitung pendapatan dari penjualan tersebut.',
'Bkm_Guide_Faq_7_Q' => 'Mengapa pelanggan tidak menerima email?',
'Bkm_Guide_Faq_7_A' => 'Buka pemesanan: daftar pesannya menunjukkan apakah setiap email terkirim, gagal, atau dilewati, beserta alasannya.',
'Bkm_Staff_Removed' => 'dihapus',
'Bkm_Staff_Not_Bookable' => 'Tidak lagi dapat dipesan',
'Bkm_Requests_Cut' => 'Menampilkan {n} terlama. Tanggapi sebagian untuk melihat sisanya, atau gunakan pencarian.',

