'Mkg_Guide_Allows' => 'Yang dapat dilakukan',
'Mkg_Guide_Perm_marketing_dashboard' => 'Melihat dasbor pemasaran: total dan kampanye terbaru.',
'Mkg_Guide_Perm_marketing_campaigns' => 'Membuat, mengedit, mengirim, dan menghapus kampanye, serta melihat penerimanya.',
