'Mkg_Guide_Perm_marketing_templates' => 'Mengelola templat SMS, WhatsApp, dan email.',
'Mkg_Guide_Perm_marketing_reports' => 'Membuka laporan pemasaran.',
'Mkg_Guide_Perm_marketing_settings' => 'Menyiapkan saluran (SMS, WhatsApp, pengirim email), penjadwalan, dan ukuran batch.',
'Mkg_Guide_Faq' => 'Pertanyaan umum',
'Mkg_Guide_Faq_1_Q' => 'Kampanye saya tetap pada status Mengirim dan tidak ada yang terkirim.',
'Mkg_Guide_Faq_1_A' => 'Pengirim latar belakang belum memprosesnya. Setelah 30 menit tanpa kemajuan, tombol Kirim Sekarang muncul kembali: klik untuk melanjutkan. Jika terus terjadi, minta administrator platform Anda untuk memeriksa apakah tugas latar belakang (queue worker) berjalan.',
'Mkg_Guide_Faq_2_Q' => 'Penerima menampilkan "Skipped: Email channel disabled".',
'Mkg_Guide_Faq_2_A' => 'Aktifkan opsi Aktifkan Email di Pengaturan Pemasaran, lalu kirim ulang kampanye.',
'Mkg_Guide_Faq_3_Q' => 'Penerima menampilkan "No mail server configured".',
'Mkg_Guide_Faq_3_A' => 'Kampanye email hanya dikirim melalui server email Anda sendiri. Tambahkan di Pengaturan > Pengaturan Email.',
'Mkg_Guide_Faq_4_Q' => 'Jumlah orang yang menerima pesan lebih sedikit daripada jumlah di segmen saya.',
'Mkg_Guide_Faq_4_A' => 'Pelanggan tanpa alamat email (Email) atau nomor telepon (SMS, WhatsApp) dilewati. Buka kampanye untuk melihat siapa yang dilewati dan alasannya.',
'Mkg_Guide_Faq_5_Q' => 'Apakah Terkirim berarti pelanggan sudah menerimanya?',
'Mkg_Guide_Faq_5_A' => 'Terkirim berarti server email atau gateway Anda telah menerima pesan tersebut. Pengiriman ke kotak masuk, pembukaan pesan, dan penyaringan spam tidak dilacak.',
'Mkg_Guide_Faq_6_Q' => 'Bisakah saya mengedit kampanye setelah mengirimnya?',
'Mkg_Guide_Faq_6_A' => 'Tidak. Kampanye yang sedang dikirim dan sudah terkirim dikunci; buat kampanye baru sebagai gantinya.',
'Mkg_Guide_Faq_7_Q' => 'Pesan WhatsApp saya tidak sampai.',
'Mkg_Guide_Faq_7_A' => 'Lebih dari 24 jam setelah pelanggan terakhir kali mengirim pesan kepada Anda, WhatsApp hanya mengirimkan templat yang disetujui Meta. Gunakan WhatsApp Cloud API dan pilih templat yang disetujui di kampanye.',
'Mkg_Guide_Faq_8_Q' => 'Jika saya mengirim ulang kampanye, apakah pelanggan akan menerimanya dua kali?',
'Mkg_Guide_Faq_8_A' => 'Melanjutkan kampanye yang macet hanya mengirim ke penerima yang masih tertunda, sehingga tidak ada yang sudah dijangkau yang dikirimi pesan lagi. Mengirim ulang kampanye yang gagal akan memulai dari awal dengan daftar baru.',

