'Pd_Installments' => 'Cicilan',
'Pd_Single_Payment' => 'Pembayaran tunggal',
'Pd_Guide_How_Title' => 'Cara kerjanya',
'Pd_Guide_How_Intro' => 'Perangkat POS adalah terminal kartu atau mesin kasir fiskal di samping kasir. Stocky mengirimkan jumlahnya, menunggu pelanggan membayar, dan mencatat pembayaran hanya setelah perangkat menyetujuinya.',
'Pd_Guide_Step_1' => 'Tambahkan perangkat di sini: model, gudang, dan metode pembayaran yang digunakan untuk mencatat pembayaran kartunya (misalnya "Kartu Kredit").',
'Pd_Guide_Step_2' => 'Pilih cara Stocky menjangkaunya: bridge lokal di komputer kasir, atau cloud API penyedia Anda. Masukkan ID dan kunci dari bank atau penyedia Anda.',
'Pd_Guide_Step_3' => 'Tekan Uji koneksi. Perangkat bridge harus diuji dari komputer kasir tempat bridge berjalan.',
'Pd_Guide_Step_4' => 'Di POS, pilih metode pembayaran tersebut, tekan "Tagih di perangkat" dan biarkan pelanggan membayar. Penjualan dapat diselesaikan setelah perangkat menyetujuinya.',
'Pd_Guide_Step_5' => 'Periksa Transaksi untuk pembayaran kartu yang diambil tanpa penjualan (misalnya, checkout yang ditinggalkan), lalu batalkan atau kembalikan dananya.',
'Pd_Guide_Bridge_Text' => 'Untuk perangkat yang dikendalikan oleh SDK vendor di PC kasir (pemasangan USB, serial, atau LAN). Browser tidak dapat menggunakan SDK secara langsung, jadi program bridge kecil membungkusnya dan menunggu permintaan di komputer ini.',
'Pd_Guide_Bridge_Point_1' => 'POS mengirim setiap permintaan ke URL bridge dari browser kasir; server Stocky tidak perlu menjangkau jaringan toko Anda.',
'Pd_Guide_Bridge_Point_2' => 'Permintaan dan respons ditandatangani dengan rahasia bersama, sehingga persetujuan tidak dapat dipalsukan dari browser.',
'Pd_Guide_Bridge_Point_3' => 'Instal dan jalankan bridge di setiap komputer yang menerima pembayaran kartu dengan perangkat ini.',
'Pd_Guide_Cloud_Text' => 'Untuk penyedia yang menjangkau perangkat melalui internet. Server Stocky memanggil API, jadi tidak ada yang perlu diinstal di komputer kasir.',
'Pd_Guide_Cloud_Point_1' => 'URL API harus https:// pada alamat publik.',
'Pd_Guide_Cloud_Point_2' => 'Selama pelanggan membayar, Stocky menanyakan status setiap 2 detik, jadi endpoint status harus mengenali pembayaran berdasarkan referensinya; jika API merespons sebelum kartu selesai ("pending"), hasil polling yang menentukan.',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'IDE280 adalah mesin kasir fiskal generasi baru (YN ÖKC) dengan pembaca kartu. Perangkat ini biasanya diintegrasikan melalui SDK ECR / GMP3 dari Ingenico, atau melalui layanan integrasi bank Anda.',
'Pd_Guide_Ide280_Point_1' => 'Pasangkan perangkat dengan komputer kasir seperti yang dijelaskan dalam dokumentasi Ingenico / bank, lalu arahkan bridge (atau pengaturan API) ke perangkat tersebut.',
'Pd_Guide_Ide280_Point_2' => 'Jumlah dikirim dalam bentuk desimal dan dalam kuruş (amount_minor), dengan mata uang TRY / 949.',
'Pd_Guide_Ide280_Point_3' => 'Dengan "Struk fiskal lengkap", setiap item membawa departemen perangkat dari tarif PPN-nya — sesuaikan departemen PPN dengan cara perangkat diprogram.',
'Pd_Guide_Protocol_Title' => 'Kontrak bridge / API',
'Pd_Guide_Protocol_Intro' => 'Stocky berkomunikasi dalam JSON dengan bridge atau API. Path di bawah ini adalah default dan dapat diubah per perangkat di bagian Lanjutan.',
'Pd_Guide_Operation' => 'Operasi',
'Pd_Guide_Default_Endpoint' => 'Endpoint default',
'Pd_Guide_When' => 'Kapan',
'Pd_Guide_When_Ping' => 'Tombol Uji koneksi.',
'Pd_Guide_When_Sale' => 'Kasir menekan "Tagih di perangkat". Dapat merespons setelah kartu selesai, atau langsung dengan status "pending".',
'Pd_Guide_When_Status' => 'Setiap 2 detik selama pembayaran tertunda.',
'Pd_Guide_When_Cancel' => 'Kasir membatalkan saat menunggu kartu.',
'Pd_Guide_When_Void' => 'Membatalkan pembayaran (hari yang sama, seluruh jumlah).',
'Pd_Guide_When_Refund' => 'Mengembalikan dana sebagian atau seluruh pembayaran.',
'Pd_Guide_Request_Title' => 'Permintaan',
'Pd_Guide_Request_Text' => 'Body yang dikirim Stocky untuk penjualan. Pengembalian dana dan pembatalan membawa pembayaran asli sebagai "original".',
'Pd_Guide_Response_Title' => 'Respons',
'Pd_Guide_Response_Text' => 'Nama field dibaca secara fleksibel (juga di bawah "data"); "status" atau response_code "00" menentukan hasilnya. Nomor kartu disimpan dalam bentuk tersamar.',
'Pd_Guide_Signing_Title' => 'Penandatanganan (bridge)',
'Pd_Guide_Signing_Text' => 'Bridge sebaiknya memeriksa tanda tangan Stocky, dan wajib menandatangani body respons persisnya serta mengembalikan "reference" dan "operation" — respons tanpa tanda tangan, atau respons tentang operasi lain, akan ditolak.',
'Pd_Guide_Browser_Title' => 'Akses browser (bridge)',
'Pd_Guide_Browser_Text' => 'Halaman POS memanggil bridge dari browser, jadi bridge harus merespons dengan header CORS ini (termasuk preflight OPTIONS).',
'Pd_Guide_Safety_Title' => 'Perlu diketahui',
'Pd_Guide_Safety_1' => 'Penjualan hanya disimpan jika ada pembayaran perangkat yang disetujui dengan jumlah yang sama; satu pembayaran perangkat tidak pernah dapat membayar dua penjualan.',
'Pd_Guide_Safety_2' => 'Menutup jendela pembayaran setelah kartu ditagih akan membatalkan tagihan tersebut terlebih dahulu.',
'Pd_Guide_Safety_3' => 'Jika perangkat tidak merespons tepat waktu, pembayaran ditampilkan sebagai "Tidak ada respons": periksa perangkat, dan batalkan tagihan dari Transaksi jika kartu telah ditagih.',
'Pd_Guide_Safety_4' => 'Pengembalian dana dan pembatalan di sini hanya memindahkan uang pada kartu; tidak mengubah penjualan. Catat barang yang dikembalikan di Retur Penjualan.',
'Perm_Pos_Terminals_Manage' => 'Perangkat POS: kelola, kembalikan dana & batalkan',
'Perm_Pos_Terminals_Transactions' => 'Perangkat POS: lihat transaksi',
'Pd_Check_Again' => 'Periksa lagi',
'Pd_Lost_Track' => 'Koneksi terputus sebelum perangkat merespons. Periksa perangkat, lalu tekan "Periksa lagi" — jangan menagih lagi sampai Anda yakin.',
'Pd_Close_Anyway' => 'Pembayaran kartu tidak dapat dibatalkan. Tetap tutup? Pembayaran ini tetap ada di Perangkat POS › Transaksi sebagai "Ditagih tanpa penjualan" sehingga dapat dibatalkan atau dikembalikan dananya di sana.',
'Pd_Devices_Loading' => 'Memuat perangkat kartu — coba lagi sebentar lagi.',
'Pd_Devices_Unavailable' => 'Perangkat kartu tidak dapat dimuat, sehingga metode pembayaran ini tidak dapat digunakan saat ini. Pilih metode lain atau buka ulang jendela pembayaran.',
'Pd_Saving_Sale' => 'Penjualan sedang disimpan — tunggu sebentar.',
'Pd_Check_Status' => 'Periksa status',
'Pd_Check_Status_Help' => 'Tanyakan lagi ke perangkat apakah pembayaran ini berhasil. Untuk perangkat bridge lokal, lakukan ini di komputer tempat bridge berjalan.',
