'Oc_Options_Desc' => 'Varian OpenCart memiliki stok sendiri dan dipetakan ke varian di sini. Produk yang hanya memiliki opsi, tanpa varian yang dibuat, diimpor sebagai satu produk dan stoknya tidak dibagi per opsi.',
'Oc_Cancel_Title' => 'Pesanan dibatalkan',
'Oc_Cancel_Desc' => 'Membatalkan pesanan di OpenCart akan membatalkan penjualannya di sini. Jika penjualan sudah dikirim atau memiliki retur, tidak ada yang dibatalkan: penjualan ditandai di catatannya dan di log untuk Anda tinjau.',
'Oc_Download_Connector_3' => 'Unduh untuk OpenCart 3',
'Oc_Opencart3_Title' => 'Toko OpenCart 3',
'Oc_Opencart3_Desc' => 'OpenCart 3 tidak memiliki varian sendiri, hanya opsi. Produk dengan satu opsi (misalnya Ukuran) disinkronkan dengan stok per nilai opsi, yang dipetakan ke varian di sini. Produk dengan beberapa opsi dibuatkan opsinya tanpa stok per kombinasi: stoknya disimpan pada produk secara keseluruhan, dan baris penjualannya masuk ke produk tersebut.',
'Oc_G_Title' => 'Panduan OpenCart',
'Oc_G_Open_Settings' => 'Buka pengaturan OpenCart',
'Oc_G_Your_Setup' => 'Penyiapan Anda',
'Oc_G_Your_Setup_Help' => 'Posisi workspace ini saat ini. Langkah-langkah diperbarui seiring kemajuan Anda.',
'Oc_G_Step_Install' => 'Instal {company} Connector di toko Anda',
'Oc_G_Step_Install_Help' => 'Ekstensi kecil yang memberi {company} akses ke produk, stok, dan pesanan. OpenCart sendiri tidak memiliki API untuk itu.',
'Oc_G_Step_Connect' => 'Hubungkan toko',
'Oc_G_Step_Connect_Help' => 'Tempelkan URL toko dan kunci rahasia dari halaman modul di tab Koneksi, simpan, lalu jalankan Uji koneksi.',
'Oc_G_Step_Connect_Done' => 'Terhubung: konektor {connector} pada OpenCart {opencart}.',
'Oc_G_Step_Enable' => 'Aktifkan sinkronisasi',
'Oc_G_Step_Enable_Help' => 'Tidak ada yang bergerak selama integrasi dinonaktifkan; webhook dari toko diterima lalu diabaikan.',
'Oc_G_Step_Products' => 'Tautkan produk',
'Oc_G_Step_Products_Help' => 'Ambil katalog toko atau kirim katalog Anda, sehingga setiap produk di kedua sisi tertaut sebelum stok mulai mengalir.',
'Oc_G_Step_Products_Done' => '{n} produk dan {v} varian tertaut.',
'Oc_G_Step_Orders' => 'Terima pesanan',
'Oc_G_Step_Orders_Help' => 'Setelah terhubung, pesanan baru masuk dengan sendirinya. Buat pesanan uji di toko untuk melihatnya muncul di Penjualan.',
'Oc_G_Step_Orders_No_Webhook' => 'Pesanan sudah diimpor, tetapi belum ada yang masuk melalui notifikasi toko. Jika toko tidak dapat menjangkau alamat ini, pesanan tetap masuk melalui pemeriksaan setiap beberapa menit.',
'Oc_G_Step_Orders_Done' => 'Toko sedang mengirim notifikasi pesanan.',
'Oc_G_Install_Title' => 'Instal konektor',
'Oc_G_Install_Intro' => 'Pilih versi OpenCart Anda. Konektor diinstal melalui penginstal ekstensi bawaan OpenCart; tidak ada file yang diedit secara manual.',
'Oc_G_Opencart_4' => 'OpenCart 4.x',
'Oc_G_Opencart_3' => 'OpenCart 3.x',
'Oc_G_I4_1' => 'Unduh konektor untuk OpenCart 4.',
'Oc_G_I4_2' => 'Di admin OpenCart Anda, buka {path}, unggah file, lalu klik Install di sebelahnya.',
'Oc_G_I4_3' => 'Buka {path}, cari {name} dan klik Install, lalu Edit.',
'Oc_G_I3_1' => 'Unduh konektor untuk OpenCart 3.',
'Oc_G_I3_2' => 'Di admin OpenCart Anda, buka {path}, unggah file, lalu tunggu hingga langkah-langkahnya selesai.',
'Oc_G_I3_3' => 'Buka {path}, cari {name} dan klik Install, lalu Edit.',
'Oc_G_I_4' => 'Halaman modul menampilkan URL toko dan kunci rahasia. Salin keduanya.',
'Oc_G_I_5' => 'Kembali ke sini, tempelkan keduanya di tab Koneksi, simpan, lalu jalankan {test}. Langkah ini juga memberi tahu toko ke mana notifikasi pesanan dikirim.',
'Oc_G_Requirements' => 'Yang dibutuhkan toko',
'Oc_G_Requirements_Desc' => 'OpenCart 3.0 atau 4.0 ke atas, PHP dengan cURL (standar di hosting mana pun), dan alamat toko yang dapat dijangkau dari internet. Jika toko berada di jaringan privat, pesanan tetap masuk melalui pemeriksaan yang berjalan setiap beberapa menit, selama workspace ini dapat menjangkau toko.',
'Oc_G_First_Title' => 'Sinkronisasi pertama',
'Oc_G_First_Shop_Has' => 'Toko sudah memiliki katalog',
'Oc_G_First_Shop_Has_Text' => 'Ambil produk di tab Produk. Produk dicocokkan berdasarkan model atau SKU dengan kode produk Anda dan dibuat jika belum ada; centang opsi stok untuk mengambil jumlah di toko sebagai stok awal.',
'Oc_G_First_Company_Has' => '{company} memiliki katalog',
'Oc_G_First_Company_Has_Text' => 'Kirim produk. Produk yang belum ada dibuat di toko beserta stoknya; produk yang sudah ada ditautkan berdasarkan model atau SKU lalu diperbarui.',
'Oc_G_First_Both' => 'Kedua sisi memiliki produk',
'Oc_G_First_Both_Text' => 'Ambil terlebih dahulu, agar produk toko yang sudah ada ditautkan alih-alih diduplikasi, lalu kirim untuk membuat yang belum ada di toko. Samakan kode produk dan model di kedua sisi.',
'Oc_G_Stock_Master' => '{company} memegang angka stok',
'Oc_G_Stock_Master_Desc' => 'Setelah sinkronisasi pertama, jumlah di toko selalu ditulis dari {company}. Mengedit jumlah di OpenCart tidak berpengaruh permanen: pergerakan berikutnya atau pemeriksaan per jam akan menimpanya.',
'Oc_G_How_Title' => 'Cara kerjanya',
'Oc_G_T_Products' => 'Produk',
'Oc_G_Products_1' => 'Produk dicocokkan berdasarkan kodenya di sini dengan model dan SKU di toko. Tautan tersebut diingat, sehingga mengganti nama produk setelahnya tidak memutusnya.',
'Oc_G_Products_2' => 'Saat {company} mengirim produk, sistem mengatur model, SKU, nama, harga, status, dan stok. Deskripsi, gambar, dan kategori hanya ditulis saat produk baru di toko atau belum memilikinya, sehingga teks yang ditulis di OpenCart tetap terjaga.',
'Oc_G_Products_3' => 'Produk yang disembunyikan dari toko daring atau tidak dijual di sini tidak dibuat di toko; produk yang sudah tertaut justru dinonaktifkan di sana.',
'Oc_G_T_Variants' => 'Varian dan opsi',
'Oc_G_Variants_4' => 'OpenCart 4 memiliki varian sungguhan (produk dengan pilihan Warna dan Ukuran), masing-masing dengan stok sendiri. Varian tersebut dipetakan ke varian Anda di kedua arah, dan masing-masing dicocokkan berdasarkan modelnya sendiri.',
'Oc_G_Variants_3' => 'OpenCart 3 tidak memiliki varian, hanya opsi, dan stok per nilai opsi. Produk dengan satu opsi (misalnya Ukuran) disinkronkan dengan stok per nilai, yang dipetakan ke varian Anda. Produk dengan beberapa opsi dibuatkan opsinya tanpa stok per kombinasi: stoknya tetap pada produk secara keseluruhan, dan baris penjualannya masuk ke produk tersebut.',
'Oc_G_Variants_Multi' => 'Produk toko yang hanya memiliki opsi, tanpa varian yang dibuat, diimpor sebagai satu produk; hal ini dicatat di log.',
'Oc_G_T_Stock' => 'Stok',
'Oc_G_Stock_1' => 'Dengan sakelar stok aktif, setiap pergerakan di sini (penjualan, retur, pembelian, penyesuaian, transfer) memperbarui toko dalam hitungan detik, setelah halaman merespons, sehingga kasir tidak pernah menunggu toko.',
'Oc_G_Stock_2' => 'Sekali setiap jam, setiap produk tertaut diperiksa dan dikoreksi, yang mencakup perubahan massal yang tidak terdeteksi oleh pengiriman langsung. Tab Stok mengirim semuanya sesuai permintaan.',
'Oc_G_Stock_3' => 'Layanan, produk yang ditandai selalu tersedia, dan combo yang komponennya tidak terbatas ditampilkan sebagai selalu tersedia di toko. Pilih gudang di tab Koneksi untuk menghitung hanya gudang tersebut; jika tidak, semua gudang dijumlahkan.',
'Oc_G_T_Orders' => 'Pesanan dan status',
'Oc_G_Orders_1' => 'Pesanan baru atau yang berubah langsung diumumkan oleh toko dan dibaca ulang melalui koneksi bertanda tangan, sehingga isi notifikasi itu sendiri tidak dipercaya. Setiap beberapa menit, pemeriksaan mengambil apa pun yang terlewat oleh notifikasi. Setiap pesanan menjadi satu penjualan dengan referensi OC-<order number>; pelanggan dicocokkan berdasarkan email atau dibuat baru.',
'Oc_G_Col_List' => 'Daftar status',
'Oc_G_Col_Meaning' => 'Fungsinya di sini',
'Oc_G_Col_Default' => 'Diatur dari toko Anda',
'Oc_G_Default_Commit' => 'Status yang mengurangi stok di OpenCart (secara bawaan Pending, Processing, Shipped, Complete)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'Daftar ini diisi dari toko Anda pada koneksi pertama dan dapat diubah di tab Koneksi. Samakan daftar pertama dengan status yang mengurangi stok di OpenCart, agar kedua sisi memindahkan stok pada langkah yang sama.',
'Oc_G_Orders_3' => 'Pesanan dengan item yang tidak cocok dengan produk mana pun akan ditahan, dan produknya diimpor dari toko jika ada di sana. Pesanan yang ditahan dicoba lagi pada setiap pemeriksaan terjadwal; setelah dua belas kali percobaan, pesanan dicatat di log dan dibiarkan untuk Anda ambil secara manual.',
'Oc_G_T_Cancel' => 'Pembatalan dan pengembalian dana',
'Oc_G_Cancel_1' => 'Saat pesanan mencapai status dibatalkan di toko, penjualannya di sini dibatalkan: stok kembali, pembayarannya dihapus, dan penjualan dihapus, sama persis seperti menghapusnya di halaman Penjualan.',
'Oc_G_Cancel_2' => 'Penjualan yang sudah dikirim, memiliki retur, atau diterima oleh otoritas pajak tidak pernah dibatalkan oleh toko. Penjualan tersebut ditandai di catatannya dan di log untuk Anda tinjau.',
'Oc_G_Cancel_3' => 'Jika pesanan diaktifkan kembali di toko setelahnya, pesanan masuk lagi sebagai penjualan baru.',
'Oc_G_T_Automation' => 'Sakelar otomatisasi',
'Oc_G_Auto_1' => 'Impor pesanan secara otomatis: notifikasi pesanan dan pemeriksaan terjadwal. Jika nonaktif, pesanan hanya masuk saat Anda mengambilnya di tab Pesanan.',
'Oc_G_Auto_2' => 'Kirim stok secara otomatis: pembaruan stok langsung dan pemeriksaan per jam. Jika nonaktif, toko hanya berubah saat Anda mengirim stok secara manual.',
'Oc_G_Auto_3' => 'Kirim perubahan produk secara otomatis: produk yang dibuat atau diedit di sini langsung memperbarui toko. Jika nonaktif, gunakan tab Produk.',
'Oc_G_T_Faq' => 'Pertanyaan',
'Oc_G_Q_Secret' => 'Uji koneksi menyatakan kunci rahasia tidak cocok',
'Oc_G_A_Secret' => 'Buka modul {company} Connector di OpenCart dan salin kembali kunci rahasianya; modul yang diinstal ulang mendapat kunci baru. Tempelkan di tab Koneksi dan simpan sebelum menguji.',
'Oc_G_Q_Clock' => 'Uji koneksi menyatakan jam toko terlalu jauh selisihnya',
'Oc_G_A_Clock' => 'Permintaan bertanda tangan membawa waktu dan ditolak jika kedua jam berselisih lebih dari lima menit. Atur tanggal dan waktu di server toko.',
'Oc_G_Q_Redirect' => 'Uji koneksi menyatakan toko mengalihkan ke alamat lain',
'Oc_G_A_Redirect' => 'Toko Anda merespons di alamat yang berbeda, biasanya https alih-alih http atau dengan www. Gunakan alamat yang ditampilkan dalam pesan sebagai URL toko.',
'Oc_G_Q_Not_Answering' => 'Uji koneksi menyatakan konektor tidak merespons',
'Oc_G_A_Not_Answering' => 'Alamat tersebut bukan toko OpenCart, atau modul belum diinstal atau dinonaktifkan. Periksa URL toko, lalu pastikan {company} Connector tampil sebagai terinstal dan aktif di Extensions → Modules.',
'Oc_G_Q_No_Orders' => 'Pesanan dibuat di toko tetapi baru muncul beberapa menit kemudian',
'Oc_G_A_No_Orders' => 'Toko tidak dapat menjangkau workspace ini, sehingga pesanan hanya masuk melalui pemeriksaan terjadwal. Periksa alamat {company} di halaman modul: alamat itu harus dapat dijangkau dari server toko. Menjalankan Uji koneksi akan mendaftarkannya kembali.',
'Oc_G_Q_Stock_Wrong' => 'Jumlah di toko salah',
'Oc_G_A_Stock_Wrong' => 'Kirim stok di tab Stok, yang menulis ulang setiap produk tertaut dari angka di sini. Jika terus bergeser, pastikan sakelar stok aktif dan tidak ada yang mengedit jumlah di OpenCart.',
'Oc_G_Q_Out_Of_Stock' => 'Produk tampil habis di toko padahal ada stok di sini',
'Oc_G_A_Out_Of_Stock' => 'Di OpenCart 3, produk dengan beberapa opsi menyimpan stoknya pada produk secara keseluruhan; periksa jumlah produk di toko, bukan opsinya. Untuk produk apa pun, kirim stok sekali lalu lihat log untuk produk tersebut.',
'Oc_G_Q_Held' => 'Log menyatakan sebuah pesanan ditahan',
'Oc_G_A_Held' => 'Salah satu itemnya tidak cocok dengan produk mana pun di sini dan tidak dapat diimpor dari toko, biasanya karena produk tersebut telah dihapus di sana. Buat atau tautkan produknya, lalu ambil pesanan di tab Pesanan.',
'Oc_G_Q_Deleted_Sale' => 'Saya menghapus penjualan hasil impor dan penjualan itu muncul lagi',
'Oc_G_A_Deleted_Sale' => 'Selama pesanan masih aktif di toko, notifikasi atau pemeriksaan berikutnya akan mengimpornya lagi. Sebaiknya batalkan pesanan di toko, yang akan membatalkan penjualannya di sini.',
'Oc_G_Q_Uninstall' => 'Bagaimana cara memutuskan koneksi toko?',
'Oc_G_A_Uninstall' => 'Nonaktifkan sinkronisasi di tab Koneksi; tidak ada yang bergerak selama nonaktif. Untuk menghapus integrasi dari toko, copot pemasangan {company} Connector di Extensions → Modules.',
'Oc_Full_Guide' => 'Buka panduan lengkap',
'Comm_Receipt_Account_Hint' => 'Akun kas atau bank tempat pembayaran ini keluar. Saldonya berkurang sebesar jumlah tersebut dan buku besar memposting Beban Komisi Penjualan (Sales Commission Expense) terhadapnya.',
'Comm_G_Q_Ledger' => 'Apa pengaruh pembayaran komisi terhadap akun?',
'Comm_G_A_Ledger' => 'Saat Anda membuat tanda terima dan memilih akun, saldo akun tersebut berkurang sebesar jumlah tanda terima dan, jika jurnal otomatis aktif, sebuah jurnal diposting: debit Beban Komisi Penjualan (Sales Commission Expense, 5200-COMM), kredit akun kas atau bank yang dipilih. Tanpa akun yang dipilih, kredit masuk ke akun Kas (Cash) bawaan dan tidak ada saldo yang berubah.',
'Hide_Zero_Decimals' => 'Sembunyikan Desimal Nol',
'Sys_Hide_Zero_Decimals_Help' => 'Tampilkan jumlah bilangan bulat tanpa desimalnya: 100.00 menjadi 100, sedangkan 100.50 tetap dengan desimalnya. Hanya tampilan; nilai tersimpan dan perhitungan tidak berubah.',
