'SW_Adjust' => 'Sesuaikan Saldo',
'SW_Top_Up_Help' => 'Uang yang dibayarkan kepada pemasok di muka. Uang keluar dari akun yang dipilih dan disimpan di dompet hingga digunakan untuk pembelian.',
'SW_Refund_Help' => 'Pemasok mengembalikan sebagian uang muka secara tunai. Jumlahnya keluar dari dompet dan masuk ke akun yang dipilih.',
'SW_Adjust_Help' => 'Koreksi manual tanpa pergerakan kas. Alasan wajib diisi dan disimpan di buku besar.',
