'SW_Adjust_Debit' => 'Kurangi dari dompet',
'SW_Pay_From_Wallet' => 'Bayar dari dompet pemasok',
'SW_Pay_From_Wallet_Help' => 'Jumlahnya diambil dari saldo prabayar di pemasok ini. Tidak memerlukan akun atau metode pembayaran.',
'SW_Credit_To_Wallet' => 'Kreditkan ke dompet pemasok',
'SW_Credit_To_Wallet_Help' => 'Alih-alih tunai, pemasok menyelesaikan retur ini sebagai kredit dompet yang dapat Anda gunakan untuk pembelian berikutnya.',
'SW_Disabled_Hint' => 'Dompet Pemasok dinonaktifkan. Aktifkan di Pengaturan Sistem > Fitur (juga memerlukan fitur paket Dompet Pemasok).',
