'Purchase_Update_Selling_Price' => 'Edit Harga Jual pada Pembelian',
'Sys_Purchase_Update_Selling_Price_Help' => 'Menambahkan kolom harga jual di setiap baris pembelian, di sebelah biaya. Harga yang diketik di sana menggantikan harga jual produk saat pembelian disimpan; kosongkan untuk mempertahankan harga saat ini.',
'Current_Selling_Price' => 'Harga jual saat ini',
'Keep_Current_Price' => 'Kosongkan untuk mempertahankan harga saat ini',
'Selling_Price_In_Base_Currency' => 'Diisi dalam mata uang dasar',
'Purchase_Update_Product_Cost' => 'Perbarui Biaya Produk pada Pembelian',
'Sys_Purchase_Update_Product_Cost_Help' => 'Saat pembelian yang diterima disimpan, biaya setiap produk menjadi biaya satuan bersih pada baris pembeliannya (setelah diskon baris, tanpa pajak, per satuan dasar). Pembelian yang tertunda dan dipesan tidak mengubahnya.',
'Show_Stock_In_Search_Results' => 'Tampilkan Stok di Hasil Pencarian',
'Show_Stock_In_Search_Results_Help' => 'Tampilkan jumlah tersedia setiap produk di sebelahnya pada dropdown pencarian POS.',
'Layout_6_Tabular' => 'Tata Letak 6 - Tabel',
'Show_Signature_Line' => 'Tampilkan Baris Tanda Tangan',
'Show_Signature_Line_Desc' => 'Mencetak baris tanda tangan pelanggan kosong di bawah struk, apa pun tata letak yang dipilih.',
'Customer_Signature' => 'Tanda tangan pelanggan',
'Set_Signature_Label' => 'Label baris tanda tangan (kosong = "Tanda tangan pelanggan")',
'Oc_Code_Source' => 'Sumber kode produk',
'Oc_Code_Source_Help' => 'Kolom OpenCart mana yang menjadi kode produk di sini. Model wajib diisi di OpenCart, sehingga sebagian toko mengetikkan kategori atau jenis produk ke dalamnya dan menyimpan kode artikel sebenarnya di SKU, ISBN, UPC, EAN, JAN, atau MPN; pilih kolom tersebut untuk toko seperti itu. Model, lalu SKU, digunakan jika kolom yang dipilih kosong. Berlaku untuk produk yang diambil, pencocokan, dan pengiriman.',
'Oc_Code_Source_Model' => 'Model (bawaan)',
'Oc_Code_Source_Sku' => 'SKU',
'Oc_Connector_Link' => 'Situs web konektor',
'Oc_Connector_Link_Help' => 'Alamat situs web Anda. OpenCart menautkan nama konektor ke alamat ini di halaman Extensions > Installer. Kosongkan untuk menggunakan alamat workspace {company} ini.',
'Store_Warehouses_Help' => 'Stok yang ditampilkan dan dikurangi secara daring berasal dari gudang-gudang ini. Selama "Batasi produk berdasarkan gudang" aktif di Fitur, toko juga hanya menampilkan produk yang termasuk dalam (atau memiliki stok di) gudang-gudang ini.',
